-- 13) ID conflict retained; live profile ledger untouched
do
    resetDb()
    SpectrumFederationDB = {
        lootHelper = {
            profiles = {
                p1 = { _consumables = { requestedItems = { ["999"] = { itemId = 999, goal = 1 } } } },
