    loadModule("SpectrumFederation/modules/UI/Settings/Style.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/Widgets/Section.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/PageBuilder.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/Control/Controls.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/Dialogs.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/DefinitionRenderer.lua")
    if not SF.ItemDisplay then
        loadModule("SpectrumFederation/modules/UI/Settings/ItemDisplay.lua")
    end
    loadModule("SpectrumFederation/modules/UI/Settings/Pages/GuildSuppliesConfiguration.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/Pages/GuildSuppliesLogs.lua")

    local configPage = SF.SettingsUI.pagesById.guildSuppliesConfiguration
    local logsPage = SF.SettingsUI.pagesById.guildSuppliesLogs
    assertTrue(configPage ~= nil, "Configuration page registered")
    assertTrue(logsPage ~= nil, "Logs page registered")
    assertTrue(type(configPage.Build) == "function" and type(configPage.Refresh) == "function",
        "Configuration exposes Build/Refresh")
    assertTrue(type(logsPage.Build) == "function" and type(logsPage.Refresh) == "function",
        "Logs exposes Build/Refresh")
    assertEq(SF.SettingsUI.categories.guildSupplies.name, "Raid Supplies",
        "category name localized through Loc default")

    local function findEditBoxes(node, out)
        out = out or {}
        if node.kind == "EditBox" then
            out[#out + 1] = node
        end
        for _, child in ipairs(node.children or {}) do
            findEditBoxes(child, out)
        end
        return out
    end
    local function findButtons(node, out)
        out = out or {}
        if node.kind == "Button" and node.text then
            out[#out + 1] = node
        end
        for _, child in ipairs(node.children or {}) do
            findButtons(child, out)
        end
        return out
    end
    local function findDropdowns(node, out)
        out = out or {}
        if node.kind == "DropdownButton" then
            out[#out + 1] = node
        end
        for _, child in ipairs(node.children or {}) do
            findDropdowns(child, out)
        end
        return out
    end

    -- Configuration: Build renders; bank-tab onCommit; New Campaign confirmation binding.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    GS:CreateStagedRecord()
    startCampaign()

    local configPanel = makeRegion("Frame", "GSConfigPanel", nil)
    configPanel:SetSize(600, 800)
    local beforeBuild = #created
    configPage:Build(configPanel)
    assertTrue(#created > beforeBuild, "Configuration Build creates controls")
    assertTrue(configPanel.__sfPageBuilder ~= nil, "Configuration uses DefinitionRenderer:Build")
    local pageDef = configPanel.__sfPageDef
    assertTrue(type(pageDef) == "table", "Build stores page definition")
    local foundBankDropdown, foundGoalCommit, foundStatusDisplay, foundNextStepHelp = false, false, false, false
    for _, sec in ipairs(pageDef.sections or {}) do
        for _, item in ipairs(sec.items or {}) do
            if item.type == "dropdown" and item.label
                and tostring(item.label):find("Bank Tab", 1, true)
                and type(item.onValueChanged) == "function" then
                foundBankDropdown = true
            end
            if item.type == "consumableRequestedList" and type(item.onGoalCommit) == "function" then
                foundGoalCommit = true
            end
            if sec.id == "gsStatus" and item.type == "display" and type(item.get) == "function" then
                foundStatusDisplay = true
            end
            if sec.id == "gsStatus" and item.type == "help" and type(item.getText) == "function"
                and type(item.visible) == "function" then
                foundNextStepHelp = true
            end
        end
    end
    assertTrue(foundBankDropdown, "bank tab uses dropdown onValueChanged")
    assertTrue(foundGoalCommit, "requested list uses onGoalCommit")
    assertTrue(foundStatusDisplay, "status area uses display rows")
    assertTrue(foundNextStepHelp, "status next-step/warning help uses getText+visible")

    -- Activation guidance in Next step help (bank sample states; no Chat).
    local statusNextStepGetText
    for _, sec in ipairs(pageDef.sections or {}) do
        if sec.id == "gsStatus" then
            for _, item in ipairs(sec.items or {}) do
                if item.type == "help" and type(item.getText) == "function" then
                    statusNextStepGetText = item.getText
                    break
                end
            end
        end
        if statusNextStepGetText then break end
    end
    assertTrue(type(statusNextStepGetText) == "function", "status next-step getText captured")
    -- Unset bank tab → actionable configure-tab guidance; campaign setup still available.
    local unsetOp = GS:NewConfigOperation("set-bank-tab", "bankTab", nil)
    if unsetOp then GS:ApplyStagedConfigOperation(unsetOp) end
    GS:GetCurrentRecord().accounting._consumables.bankTab = nil
    local helpUnset = statusNextStepGetText()
    assertTrue(type(helpUnset) == "string" and helpUnset:find("Configure a Guild Bank tab", 1, true),
        "status next-step guides unset bank tab got=" .. tostring(helpUnset))
    assertTrue(helpUnset:find("Next step:", 1, true), "unset bank guidance uses Next step prefix")
    assertTrue(helpUnset:find("do not require the bank", 1, true)
        or helpUnset:find("campaign setup", 1, true),
        "status next-step notes config without open bank")
    -- Restore tab; closed bank → open-bank guidance.
    local tabOpUi = GS:NewConfigOperation("set-bank-tab", "bankTab", 2)
    assertEq(GS:ApplyStagedConfigOperation(tabOpUi), "accepted", "UI test restore bank tab")
    GS._BankContextReadinessProbe = function() return false, "bank_closed" end
    local helpClosed = statusNextStepGetText()
    assertTrue(helpClosed:find("Open the Guild Bank", 1, true),
        "status next-step guides closed bank got=" .. tostring(helpClosed))
    GS._BankContextReadinessProbe = function() return false, "log_pending" end
    local helpPending = statusNextStepGetText()
    assertTrue(helpPending:find("fresh transaction-log sample", 1, true)
        or helpPending:find("become available", 1, true),
        "status next-step guides log pending got=" .. tostring(helpPending))
    GS._BankContextReadinessProbe = function() return false, "tab_access_denied" end
    local helpDenied = statusNextStepGetText()
    assertTrue(helpDenied:find("permission to view", 1, true)
        or helpDenied:find("needs permission", 1, true),
        "status next-step guides tab access denied got=" .. tostring(helpDenied))
    GS._BankContextReadinessProbe = nil
    assertEq(#world.chat, 0, "activation guidance emits no Chat")

    -- Bank tab dropdown requires a Guild Bank observation before mutation.
    world.numGuildBankTabs = 4
    world.bankTabInfo = {
        [1] = { name = "Consumables", isViewable = true },
        [2] = { name = "Raid Materials", isViewable = true },
        [3] = { name = "Potions", isViewable = true },
        [4] = { name = "Miscellaneous", isViewable = true },
    }
    function GetNumGuildBankTabs()
        return world.numGuildBankTabs or 0
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo and world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    local function fireBankEvent(event, arg1)
        for i = 1, #created do
            local f = created[i]
            if f.registeredEvents and f.registeredEvents[event]
                and f.scripts and f.scripts.OnEvent then
                f.scripts.OnEvent(f, event, arg1)
            end
        end
        flushTimers()
    end
    local function findBankTabDef(panel)
        for _, sec in ipairs((panel.__sfPageDef and panel.__sfPageDef.sections) or {}) do
            for _, item in ipairs(sec.items or {}) do
                if item.type == "dropdown" and item.label
                    and tostring(item.label):find("Bank Tab", 1, true) then
                    return item
                end
            end
        end
        return nil
    end
    local bankDef = findBankTabDef(configPanel)
    assertTrue(bankDef ~= nil, "bank tab dropdown definition present")
    assertEq(bankDef.enabled and bankDef.enabled(), false,
        "bank tab disabled before Guild Bank observation")
    fireBankEvent("GUILDBANKFRAME_OPENED")
    configPage:Refresh(configPanel)
    bankDef = findBankTabDef(configPanel)
    assertEq(bankDef.enabled and bankDef.enabled(), true,
        "bank tab enabled after Guild Bank observation")
    local bankOpts = bankDef.options and bankDef.options() or {}
    assertTrue(#bankOpts >= 5, "bank options include clear + purchased tabs")
    local messages = {}
    local section = configPanel.__sfSections and configPanel.__sfSections.gsStatus
    local bankCtx = {
        section = {
            SetMessage = function(_, msg, sev)
                messages[#messages + 1] = { msg = msg, sev = sev }
            end,
            ClearMessage = function() end,
        },
    }
    bankDef.onValueChanged(bankCtx, 2)
    assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 2, "dropdown sets numeric bank tab")

    bankDef.onValueChanged(bankCtx, false)
    assertNil(GS:GetCurrentRecord().accounting._consumables.bankTab, "dropdown clear removes bank tab")

    -- Rejected invalid / non-offered tab leaves state unchanged.
    local opSet = GS:NewConfigOperation("set-bank-tab", "bankTab", 3)
    GS:ApplyStagedConfigOperation(opSet)
    messages = {}
    bankDef.onValueChanged(bankCtx, 9)
    assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 3, "invalid tab leaves state")
    assertTrue(#messages >= 1, "invalid tab reports an error message")

    ---------------------------------------------------------------------------
    -- Bank Tab dropdown catalog: names, permissions, cache, lifecycle (#400)
    ---------------------------------------------------------------------------
    do
        local function labelFor(opts, value)
            for i = 1, #opts do
                if opts[i].value == value then
                    return opts[i].label
                end
            end
            return nil
        end

        -- 1/2) Disabled before data; opening bank loads names.
        fireBankEvent("GUILDBANKFRAME_CLOSED")
        -- Catalog remains session-cached after close.
        bankDef = findBankTabDef(configPanel)
        assertEq(bankDef.enabled and bankDef.enabled(), true,
            "bank dropdown stays enabled from session cache after bank close")
        local tipOpen = bankDef.getDisabledTooltip and bankDef.getDisabledTooltip()
        assertNil(tipOpen, "bank tip nil while catalog loaded and authorized")

        -- Fresh catalog via guild identity change then reopen.
        local priorClub = world.guild.clubId
        world.guild.clubId = 99
        settleRoster()
        flushTimers()
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        -- Different guild has no dataset; re-init for club 99 after creating staged record.
        -- Prefer staying on club 42 and clearing by switching away/back with empty observation.
        world.guild.clubId = priorClub
        settleRoster()
        flushTimers()

        -- 3) Only purchased viewable tabs are selectable.
        world.bankTabInfo = {
            [1] = { name = "Consumables", isViewable = true },
            [2] = { name = "Officers", isViewable = false },
            [3] = { name = "Potions", isViewable = true },
            [4] = { name = "Raid Materials", isViewable = true },
        }
        world.numGuildBankTabs = 4
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        bankOpts = bankDef.options()
        assertNil(labelFor(bankOpts, 2), "non-viewable tab is not selectable")
        assertTrue(labelFor(bankOpts, 1) ~= nil, "viewable tab 1 offered")
        assertTrue(labelFor(bankOpts, 3) ~= nil, "viewable tab 3 offered")
        assertTrue(labelFor(bankOpts, 4) ~= nil, "viewable tab 4 offered")
        assertTrue(labelFor(bankOpts, 1):find("Consumables", 1, true),
            "tab 1 label uses API name")
        assertTrue(labelFor(bankOpts, 3):find("Tab 3", 1, true),
            "tab labels include numeric index")

        -- 4) Selecting Tab 3 persists numeric 3, not the name.
        -- Move off any prior tab-3 fixture so the selection allocates a fresh op.
        if GS:GetCurrentRecord().accounting._consumables.bankTab == 3 then
            bankDef.onValueChanged(bankCtx, 1)
            assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 1,
                "precondition: move off tab 3 before measuring tab-3 selection")
        end
        local beforeOpsDrop = 0
        for _ in pairs(GS:GetCurrentRecord().operations.records or {}) do
            beforeOpsDrop = beforeOpsDrop + 1
        end
        bankDef.onValueChanged(bankCtx, 3)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 3,
            "selecting Tab 3 stores numeric 3")
        assertEq(type(GS:GetCurrentRecord().accounting._consumables.bankTab), "number",
            "stored bankTab is a number")

        -- 13) No redundant operation when selecting the current tab.
        local midOps = 0
        for _ in pairs(GS:GetCurrentRecord().operations.records or {}) do
            midOps = midOps + 1
        end
        assertEq(midOps, beforeOpsDrop + 1, "first selection allocates one op")
        bankDef.onValueChanged(bankCtx, 3)
        local afterNoop = 0
        for _ in pairs(GS:GetCurrentRecord().operations.records or {}) do
            afterNoop = afterNoop + 1
        end
        assertEq(afterNoop, midOps, "reselecting current tab allocates no op")

        -- 5) Existing numeric configuration displayed correctly.
        assertEq(bankDef.get(), 3, "dropdown get returns configured numeric tab")
        local defaultText = bankDef.defaultText
        if type(defaultText) == "function" then
            defaultText = defaultText()
        end
        assertTrue(type(defaultText) == "string" and defaultText:find("Potions", 1, true),
            "default text shows configured tab name got=" .. tostring(defaultText))

        -- 6) Renaming a tab updates label without changing selected value.
        world.bankTabInfo[3].name = "Raid Potions"
        fireBankEvent("GUILDBANK_UPDATE_TABS")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 3,
            "rename keeps numeric selection")
        assertEq(bankDef.get(), 3, "get still returns 3 after rename")
        bankOpts = bankDef.options()
        assertTrue(labelFor(bankOpts, 3):find("Raid Potions", 1, true),
            "renamed tab label refreshed got=" .. tostring(labelFor(bankOpts, 3)))

        -- 7) Duplicate names remain distinguishable by number.
        world.bankTabInfo[1].name = "Supplies"
        world.bankTabInfo[4].name = "Supplies"
        fireBankEvent("GUILDBANK_UPDATE_TABS")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        bankOpts = bankDef.options()
        local lab1 = labelFor(bankOpts, 1)
        local lab4 = labelFor(bankOpts, 4)
        assertTrue(lab1 and lab1:find("Tab 1", 1, true) and lab1:find("Supplies", 1, true),
            "duplicate name tab 1 distinguished got=" .. tostring(lab1))
        assertTrue(lab4 and lab4:find("Tab 4", 1, true) and lab4:find("Supplies", 1, true),
            "duplicate name tab 4 distinguished got=" .. tostring(lab4))
        assertTrue(lab1 ~= lab4, "duplicate name labels are not identical")

        -- 11) Clearing selection preserves nil operation semantics.
        bankDef.onValueChanged(bankCtx, false)
        assertNil(GS:GetCurrentRecord().accounting._consumables.bankTab,
            "clear sentinel stores nil bankTab")
        bankDef.onValueChanged(bankCtx, false)
        local clearOps = 0
        for _ in pairs(GS:GetCurrentRecord().operations.records or {}) do
            clearOps = clearOps + 1
        end
        -- Second clear is a no-op (no extra op beyond the first clear).
        bankDef.onValueChanged(bankCtx, 3)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 3, "reselect after clear")

        -- 10) Unavailable tab data does not erase an existing setting.
        local priorTab = GS:GetCurrentRecord().accounting._consumables.bankTab
        world.bankTabInfo[3].name = nil -- incomplete API response
        fireBankEvent("GUILDBANK_UPDATE_TABS")
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, priorTab,
            "incomplete tab info does not clear configured bankTab")
        -- Restore coherent names for subsequent assertions.
        world.bankTabInfo[3].name = "Raid Potions"
        fireBankEvent("GUILDBANK_UPDATE_TABS")

        -- 8) Changing guilds does not reuse another guild's tab list.
        local tabBeforeGuild = GS:GetCurrentRecord().accounting._consumables.bankTab
        world.guild.clubId = 77
        settleRoster()
        flushTimers()
        -- Guild 77 is not configured; catalog must not offer guild 42 names.
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        bankOpts = bankDef.options()
        assertEq(#bankOpts, 0, "guild change clears prior guild tab catalog options")
        assertEq(bankDef.enabled and bankDef.enabled(), false,
            "bank dropdown disabled for new guild without observation")
        -- Opening bank on the new guild loads that guild's names only.
        world.bankTabInfo = {
            [1] = { name = "Other Guild Tab", isViewable = true },
        }
        world.numGuildBankTabs = 1
        -- Need a staged record on guild 77 to enable editing.
        assertEq(select(2, GS:CreateStagedRecord()), "accepted", "init guild 77 for catalog isolation")
        startCampaign()
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        bankOpts = bankDef.options()
        assertTrue(labelFor(bankOpts, 1) and labelFor(bankOpts, 1):find("Other Guild Tab", 1, true),
            "new guild catalog uses its own names")
        assertNil(labelFor(bankOpts, 3), "prior guild tab 3 not offered on new guild")
        -- Restore primary guild for later suites.
        world.guild.clubId = 42
        settleRoster()
        flushTimers()
        resetDb()
        initGS()
        setPlayer("Alice-Garona", "Player-1-Alice", 1)
        world.guild.clubId = 42
        settleRoster()
        GS:CreateStagedRecord()
        startCampaign()
        world.bankTabInfo = {
            [1] = { name = "Consumables", isViewable = true },
            [2] = { name = "Raid Materials", isViewable = true },
            [3] = { name = "Potions", isViewable = true },
            [4] = { name = "Miscellaneous", isViewable = true },
        }
        world.numGuildBankTabs = 4
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        bankDef.onValueChanged(bankCtx, 3)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 3,
            "restored guild 42 can select tab 3 again")
        assertTrue(tabBeforeGuild == 3 or tabBeforeGuild == nil or type(tabBeforeGuild) == "number",
            "prior tab was numeric before guild switch")

        -- 9) Closing and reopening the Guild Bank works; cache survives close.
        fireBankEvent("GUILDBANKFRAME_CLOSED")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        assertEq(bankDef.enabled and bankDef.enabled(), true,
            "catalog remains usable after bank close")
        assertTrue(#(bankDef.options()) >= 5, "options remain after bank close")
        world.bankTabInfo[4].name = "Misc Renamed"
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        assertTrue(labelFor(bankDef.options(), 4):find("Misc Renamed", 1, true),
            "reopen refreshes renamed tab")

        -- 12) Unauthorized user cannot modify the selection.
        local priorMembers = world.guild.members
        world.guild.members = {
            { name = "Alice-Garona", guid = "Player-1-Alice", rankOrder = 5 },
        }
        settleRoster()
        flushTimers()
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        assertEq(bankDef.enabled and bankDef.enabled(), false,
            "unauthorized bank dropdown disabled")
        local unauthTip = bankDef.getDisabledTooltip()
        assertTrue(type(unauthTip) == "string" and unauthTip:find("rank does not permit", 1, true),
            "unauthorized tip precedes open-bank tip got=" .. tostring(unauthTip))
        local tabBeforeDenied = GS:GetCurrentRecord()
            and GS:GetCurrentRecord().accounting._consumables.bankTab
        world.guild.members = priorMembers
        settleRoster()
        flushTimers()
        configPage:Refresh(configPanel)
        bankDef = findBankTabDef(configPanel)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, tabBeforeDenied,
            "unauthorized attempt left bankTab unchanged")

        -- Open-bank tip: close bank first so guild churn cannot re-observe.
        fireBankEvent("GUILDBANKFRAME_CLOSED")
        resetDb()
        initGS()
        setPlayer("Alice-Garona", "Player-1-Alice", 1)
        world.guild.clubId = 42
        settleRoster()
        GS:CreateStagedRecord()
        startCampaign()
        local tipBankPanel = makeRegion("Frame", "GSBankTipPanel", nil)
        tipBankPanel:SetSize(600, 800)
        tipBankPanel.shown = true
        configPage:Build(tipBankPanel)
        -- Wipe session catalog via guild identity change while bank is closed.
        -- SyncBankTabCatalogGuild runs from options/enabled; Settings roster frames
        -- are not on world.frames, so drive Sync through a Refresh while on club 55.
        world.guild.clubId = 55
        settleRoster()
        flushTimers()
        configPage:Refresh(tipBankPanel)
        bankDef = findBankTabDef(tipBankPanel)
        assertEq(#(bankDef.options()), 0,
            "guild 55 refresh clears prior guild 42 catalog options")
        world.guild.clubId = 42
        settleRoster()
        flushTimers()
        configPage:Refresh(tipBankPanel)
        bankDef = findBankTabDef(tipBankPanel)
        assertEq(bankDef.enabled and bankDef.enabled(), false,
            "bank dropdown disabled when catalog unloaded after guild churn")
        local needOpenTip = bankDef.getDisabledTooltip()
        assertTrue(type(needOpenTip) == "string"
                and needOpenTip:find("Open your Guild Bank", 1, true),
            "disabled tip asks to open Guild Bank got=" .. tostring(needOpenTip))

        -- 14) Activation readiness / bank-log sampling unchanged by selection.
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(tipBankPanel)
        bankDef = findBankTabDef(tipBankPanel)
        bankDef.onValueChanged({
            section = { SetMessage = function() end, ClearMessage = function() end },
        }, 2)
        assertEq(GS:GetCurrentRecord().accounting._consumables.bankTab, 2,
            "selection after tip panel works")
        assertEq(GS.IsBankContextSampleReady(2), false,
            "tab selection alone does not make bank sample ready")
        local readyReason = select(2, GS.IsBankContextSampleReady(2))
        assertTrue(type(readyReason) == "string" and readyReason ~= "",
            "readiness still gated on log sample got=" .. tostring(readyReason))

        -- 15) Repeated refresh / open-close does not accumulate bank listeners.
        local bankListenersBefore = 0
        for i = 1, #created do
            local f = created[i]
            if f.registeredEvents and f.registeredEvents.GUILDBANKFRAME_OPENED then
                bankListenersBefore = bankListenersBefore + 1
            end
        end
        for _ = 1, 25 do
            fireBankEvent("GUILDBANKFRAME_CLOSED")
            fireBankEvent("GUILDBANKFRAME_OPENED")
            configPage:Refresh(tipBankPanel)
        end
        local bankListenersAfter = 0
        for i = 1, #created do
            local f = created[i]
            if f.registeredEvents and f.registeredEvents.GUILDBANKFRAME_OPENED then
                bankListenersAfter = bankListenersAfter + 1
            end
        end
        assertEq(bankListenersAfter, bankListenersBefore,
            "open/close/refresh does not accumulate bank listeners")
        assertTrue(bankListenersAfter >= 1 and bankListenersAfter <= 4,
            "bank listener count stays bounded got=" .. tostring(bankListenersAfter))

        -- Restore fixture for New Campaign tests below.
        resetDb()
        initGS()
        setPlayer("Alice-Garona", "Player-1-Alice", 1)
        world.guild.clubId = 42
        settleRoster()
        GS:CreateStagedRecord()
        startCampaign()
        world.bankTabInfo = {
            [1] = { name = "Consumables", isViewable = true },
            [2] = { name = "Raid Materials", isViewable = true },
            [3] = { name = "Potions", isViewable = true },
            [4] = { name = "Miscellaneous", isViewable = true },
        }
        world.numGuildBankTabs = 4
        fireBankEvent("GUILDBANKFRAME_OPENED")
        configPage:Refresh(configPanel)
    end

    -- New Campaign UX: first campaign applies immediately; later campaigns confirm.
    local function findNewCampaignButton(panel)
        local buttons = findButtons(panel)
        for i = 1, #buttons do
            if buttons[i].text == "New Campaign" then
                return buttons[i]
            end
        end
        return nil
    end
    local function findNewCampaignDef(panel)
        local pageDefLocal = panel and panel.__sfPageDef
        for _, sec in ipairs((pageDefLocal and pageDefLocal.sections) or {}) do
            for _, item in ipairs(sec.items or {}) do
                if item.type == "button" and item.buttonText == "New Campaign" then
                    return item
                end
            end
        end
        return nil
    end

    -- (1) No existing campaign → apply immediately without a dialog.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    assertNil(GS:GetCurrentRecord().currentCampaignId, "UX: fixture has no campaign")
    configPage:Refresh(configPanel)
    local newCampaignBtn = findNewCampaignButton(configPanel)
    assertTrue(newCampaignBtn ~= nil, "New Campaign button present")
    local ncDef = findNewCampaignDef(configPanel)
    assertTrue(ncDef ~= nil, "New Campaign definition present")
    assertTrue(type(ncDef.tooltip) == "string"
            and ncDef.tooltip:find("archived and can be viewed in Logs", 1, true),
        "enabled New Campaign tooltip explains archive/Logs got=" .. tostring(ncDef and ncDef.tooltip))
    assertTrue(type(ncDef.getDisabledTooltip) == "function",
        "New Campaign keeps getDisabledTooltip")
    pendingConfirm = nil
    newCampaignBtn:Click()
    assertNil(pendingConfirm, "first New Campaign skips confirmation dialog")
    local firstCampaignId = GS:GetCurrentRecord().currentCampaignId
    assertTrue(type(firstCampaignId) == "string" and firstCampaignId ~= "",
        "first New Campaign applies immediately")

    -- Seed items/progress so a subsequent campaign can prove empty goals + retained history.
    local seedItem = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 4242 }, {
        itemId = 4242, goal = 5, removed = false,
    }))
    assertEq(GS:ApplyStagedConfigOperation(seedItem), "accepted", "UX: seed prior campaign item")
    local priorCampaignId = GS:GetCurrentRecord().currentCampaignId
    local priorItemCount = 0
    for _ in pairs(GS:GetCurrentRecord().accounting._consumables.requestedItems or {}) do
        priorItemCount = priorItemCount + 1
    end
    assertTrue(priorItemCount >= 1, "UX: prior campaign has items")

    -- (2/3) Existing campaign → confirmation; Cancel performs no operation.
    configPage:Refresh(configPanel)
    newCampaignBtn = findNewCampaignButton(configPanel)
    pendingConfirm = nil
    newCampaignBtn:Click()
    assertTrue(pendingConfirm ~= nil, "subsequent New Campaign shows confirmation")
    assertTrue((pendingConfirm.message or ""):find("will be archived", 1, true),
        "confirm copy mentions archive got=" .. tostring(pendingConfirm.message))
    assertTrue(not (pendingConfirm.message or ""):find("overwritten", 1, true),
        "confirm copy does not say overwritten")
    assertEq(GS:GetCurrentRecord().currentCampaignId, priorCampaignId,
        "cancel (no accept) leaves campaign unchanged")

    -- (6) Confirmation unavailable with existing campaign → no operation.
    local priorDialogsConfirm = SF.SettingsUI.Dialogs.Confirm
    SF.SettingsUI.Dialogs.Confirm = nil
    pendingConfirm = nil
    local beforeUnavailable = GS:GetCurrentRecord().currentCampaignId
    newCampaignBtn:Click()
    assertNil(pendingConfirm, "confirm unavailable: no dialog shown")
    assertEq(GS:GetCurrentRecord().currentCampaignId, beforeUnavailable,
        "confirm unavailable: no campaign operation applied")
    SF.SettingsUI.Dialogs.Confirm = priorDialogsConfirm

    -- (4/5) Confirm archives previous campaign; new campaign empty; history inspectable.
    pendingConfirm = nil
    newCampaignBtn:Click()
    assertTrue(pendingConfirm ~= nil, "confirm shown before accept")
    local acceptFn = pendingConfirm.data
    assertTrue(type(acceptFn) == "function", "confirm binds accept function")
    acceptFn()
    local afterCampaign = GS:GetCurrentRecord().currentCampaignId
    assertTrue(afterCampaign ~= priorCampaignId, "accept starts new campaign")
    local newItemCount = 0
    for _ in pairs(GS:GetCurrentRecord().accounting._consumables.requestedItems or {}) do
        newItemCount = newItemCount + 1
    end
    assertEq(newItemCount, 0, "new campaign starts with empty goals")
    local campArchives = GS:GetCurrentRecord().campaignArchives or {}
    assertTrue(type(campArchives[priorCampaignId]) == "table",
        "previous campaign configuration archived for Logs inspection")
    assertTrue(GS:GetCurrentRecord().campaigns[priorCampaignId] ~= nil,
        "prior campaign record retained for Logs")

    -- (8) Repeated clicks do not create multiple campaigns without confirm.
    local midId = GS:GetCurrentRecord().currentCampaignId
    pendingConfirm = nil
    newCampaignBtn:Click()
    newCampaignBtn:Click()
    assertTrue(pendingConfirm ~= nil, "repeat click still requires confirmation")
    assertEq(GS:GetCurrentRecord().currentCampaignId, midId,
        "repeat click without accept creates no extra campaign")
    -- Dismiss without accepting.
    pendingConfirm = nil
    assertEq(GS:GetCurrentRecord().currentCampaignId, midId,
        "dismissed confirm leaves single campaign")

    -- (7) Concurrent campaign change while the dialog is open rejects the stale bound op.
    pendingConfirm = nil
    newCampaignBtn:Click()
    local boundAccept = pendingConfirm.data
    assertTrue(type(boundAccept) == "function", "stale-case confirm binds accept")
    local concurrent = GS:NewCampaignOperation()
    local concStatus = GS:ApplyStagedCampaignOperation(concurrent)
    assertEq(concStatus, "accepted", "concurrent campaign applies while dialog open")
    local midCampaign = GS:GetCurrentRecord().currentCampaignId
    local okCall = pcall(boundAccept)
    assertTrue(okCall, "bound accept does not error")
    assertEq(GS:GetCurrentRecord().currentCampaignId, midCampaign,
        "stale bound campaign op does not overwrite newer campaign")
    assertTrue(GS:GetCurrentRecord().operations.records[concurrent.id] ~= nil,
        "concurrent accepted op retained")

    -- Cached Refresh after setup/campaign changes (no rebuild).
    local refreshCalls = 0
    local realRefresh = SF.SettingsUI.DefinitionRenderer.Refresh
    SF.SettingsUI.DefinitionRenderer.Refresh = function(self, panel)
        refreshCalls = refreshCalls + 1
        return realRefresh(self, panel)
    end
    configPage:Refresh(configPanel)
    assertEq(refreshCalls, 1, "Configuration Refresh uses renderer:Refresh")
    configPanel.shown = false
    configPage:Refresh(configPanel)
    assertEq(refreshCalls, 1, "hidden Configuration skips Refresh")
    configPanel.shown = true
    SF.SettingsUI.DefinitionRenderer.Refresh = realRefresh

    -- Logs: Build/reopen without openCount crash; dropdown labels; history rows.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    GS:CreateStagedRecord()
    local c1 = startCampaign()
    local r = GS:GetCurrentRecord()
    local gen = r.accounting._consumables.generation
    r.accounting._consumableEvents[#r.accounting._consumableEvents + 1] = {
        id = "ui-don",
        type = "donation",
        itemId = 50,
        quantity = 3,
        actor = "Carol-Garona",
        generation = gen,
        timestamp = world.time,
        source = "guildbank",
    }
    startCampaign()

    local logsPanel = makeRegion("Frame", "GSLogsPanel", nil)
    logsPanel:SetSize(600, 800)
    logsPage:Build(logsPanel)
    assertTrue(logsPanel.__sfPageBuilder ~= nil, "Logs uses DefinitionRenderer:Build")
    logsPage:Build(logsPanel) -- reopen / rebuild
    assertTrue(logsPanel.__sfPageBuilder ~= nil, "Logs rebuild succeeds (no openCount crash)")

    local drops = findDropdowns(logsPanel)
    assertTrue(#drops >= 1, "campaign dropdown present")
    local drop = drops[1]
    assertTrue(type(drop.menuOptions) == "table" and #drop.menuOptions >= 1, "dropdown options built")
    local labeled = false
    for i = 1, #drop.menuOptions do
        local lab = tostring(drop.menuOptions[i].label or "")
        if lab:find("Current", 1, true) or lab:find("Archived", 1, true) then
            labeled = true
            break
        end
    end
    assertTrue(labeled, "dropdown options use readable labels not raw ids only")

    logsPage:Refresh(logsPanel)
    -- Select archived campaign via set path and refresh history.
    if drop.menuOptions[1] and drop.menuOptions[1].setSelected then
        drop.menuOptions[1].setSelected(drop.menuOptions[1].value)
    end
    logsPage:Refresh(logsPanel)
    local histRows, histTotal = GS:ListCampaignHistory(c1.id, 25, 0)
    assertTrue((histTotal or 0) >= 1, "history projection available for UI")

    -- Small-guild explicit threshold through CreateStagedRecord path used by UI.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Member" }
    settleRoster()
    local recInit, stOk, errInit = GS:CreateStagedRecord()
    assertEq(stOk, "accepted", "small guild initializes from shared officer policy: " .. tostring(errInit))
    assertEq(recInit.permission.editorRankPosition, 2, "capped officer threshold stored")
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    settleRoster()

    CreateFrame = priorCreateFrame
end

-- 2B17) Confirmation start-time finalization, reason fallback, BankLog freshness lifecycle
do
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    GS:CreateStagedRecord()
    local op = GS:NewCampaignOperation()
    local preparedTs = op.timestamp
    local preparedBase = op.baseTargetRevision
    local preparedPolicy = op.basePolicyRevision
    local preparedGuild = op.guildKey
    world.time = world.time + 120
    local okFinal, finalErr = GS:FinalizeCampaignStartTime(op)
    assertEq(okFinal, true, "finalize start time ok: " .. tostring(finalErr))
    assertTrue(op.timestamp ~= preparedTs, "timestamp finalized at accept time")
    assertEq(op.timestamp, math.floor(world.time), "final timestamp uses accept-time server time")
    assertEq(op.baseTargetRevision, preparedBase, "base target preserved")
    assertEq(op.basePolicyRevision, preparedPolicy, "base policy preserved")
    assertEq(op.guildKey, preparedGuild, "guild scope preserved")
    local status = GS:ApplyStagedCampaignOperation(op)
    assertEq(status, "accepted", "delayed finalize then apply accepted")
    assertEq(GS:GetCurrentRecord().campaigns[op.id].startedAt, op.timestamp,
        "campaign startedAt uses finalized timestamp")
    -- Exact retry must not restamp.
    local priorTs = op.timestamp
    world.time = world.time + 50
    assertEq(GS:FinalizeCampaignStartTime(op), true, "finalize no-op after accept")
    assertEq(op.timestamp, priorTs, "accepted body timestamp not restamped")
    assertEq(GS:ApplyStagedCampaignOperation(op), "duplicate", "exact replay remains duplicate")

    local generic = GS.FormatReasonText("totally_unknown_code_xyz")
    assertTrue(generic:find("could not be applied", 1, true), "generic reason localized")
    assertEq(generic:find("totally_unknown_code_xyz", 1, true), nil, "generic reason hides raw code")
    assertTrue(GS.FormatReasonText("no_campaign"):find("New Campaign", 1, true),
        "mapped no_campaign wording")
    assertTrue(GS.FormatReasonText("stale_handle"):find("out of date", 1, true),
        "mapped stale_handle wording")

    -- Production BankLog → adapter lifecycle (RequestLog / CancelTimers / ProcessLogUpdate).
    GS._BankContextReadinessProbe = nil
    world.bankTxnCounts = { [1] = 0 }
    world.bankTabInfo = {
        [1] = { name = "Supplies", isViewable = true },
    }
    world.logQueries = {}
    world.afterFns = {}
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction()
        return "deposit", "Alice-Garona", nil, 1, nil, nil, 0, 1, 1, 1
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    function QueryGuildBankLog(tab)
        world.logQueries[#world.logQueries + 1] = tab
    end
    local priorAfter = C_Timer and C_Timer.After
    C_Timer = C_Timer or {}
    C_Timer.After = function(_, fn)
        world.afterFns[#world.afterFns + 1] = fn
    end
    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    BankLog.active = true
    BankLog.bankOpen = true
    BankLog.awaitingLogUpdate = false
    BankLog.queryRetries = 0
    BankLog.queryToken = 0
    BankLog.activeContext = {
        bankTab = 1, guildGuid = "42", profileId = "p-gs",
        generation = 1, requestedSet = { [10] = true }, observedBy = "Alice-Garona",
    }
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog.lastFreshLogAt = world.time
    local priorEligible = BankLog.EligibleContext
    function BankLog:EligibleContext()
        return self.activeContext
    end

    assertEq(GS.IsBankContextSampleReady(1), true, "viewable stamped tab is ready")
    local ctx = GS.CaptureBankContext(1)
    assertEq(ctx.status, "empty", "ready viewable tab may be empty")

    -- New query invalidates prior stamp via production RequestLog.
    BankLog:RequestLog("test")
    assertEq(BankLog.lastFreshLogTab, nil, "RequestLog clears freshness stamp")
    assertEq(BankLog.awaitingLogUpdate, true, "RequestLog awaits update")
    assertEq(GS.CaptureBankContext(1).status, "unavailable", "awaiting query is unavailable")
    assertEq(GS.CaptureBankContext(1).reason, "log_pending", "log_pending while awaiting")

    -- Failed ProcessLogUpdate clears stamp and awaiting.
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    local priorCount = GetNumGuildBankTransactions
    GetNumGuildBankTransactions = function() return "bad" end
    BankLog:ProcessLogUpdate("failed")
    assertEq(BankLog.lastFreshLogTab, nil, "failed ProcessLogUpdate clears stamp")
    assertEq(BankLog.awaitingLogUpdate, false, "failed ProcessLogUpdate clears awaiting")
    GetNumGuildBankTransactions = priorCount

    -- Exhaustion path clears stamp.
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog.awaitingLogUpdate = true
    BankLog.queryRetries = 5
    BankLog:RequestLog("retry")
    assertEq(BankLog.lastFreshLogTab, nil, "exhausted RequestLog clears stamp before terminal wait")
    local terminal = world.afterFns[#world.afterFns]
    assertTrue(type(terminal) == "function", "exhaustion schedules terminal callback")
    terminal()
    assertEq(BankLog.awaitingLogUpdate, false, "exhaustion clears awaiting")
    assertEq(BankLog.lastFreshLogTab, nil, "exhaustion keeps stamp cleared")

    -- Successful update restores stamp (requires outstanding query provenance).
    BankLog.awaitingLogUpdate = true
    BankLog.pendingQuery = {
        bankTab = 1, guildGuid = "42", profileId = "p-gs", generation = 1,
        source = "guildSupplies",
    }
    BankLog.requireBankReopenForFreshness = false
    GetNumGuildBankTransactions = function() return 0 end
    BankLog:ProcessLogUpdate("success")
    assertEq(BankLog.lastFreshLogTab, 1, "successful update restores stamp")
    assertEq(GS.CaptureBankContext(1).status, "empty", "restored stamp allows empty")

    -- Slot-change inside throttle: invalidate stamp without issuing another query.
    world.logQueries = {}
    BankLog.awaitingLogUpdate = false
    BankLog.lastQueryAt = world.time
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog.lastFreshLogAt = world.time
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertEq(#world.logQueries, 0, "throttled slots_changed does not query")
    assertEq(BankLog.lastFreshLogTab, nil, "slots_changed clears stamp inside throttle")
    assertEq(GS.IsBankContextSampleReady(1), false, "readiness unavailable after throttled slot change")
    assertEq(select(2, GS.IsBankContextSampleReady(1)), "log_not_updated",
        "throttled slot change reason is log_not_updated")
    assertEq(GS.CaptureBankContext(1).status, "unavailable",
        "CaptureBankContext unavailable after throttled slot change")
    -- Genuine successful update restores readiness: must have outstanding query provenance.
    BankLog.awaitingLogUpdate = true
    BankLog.pendingQuery = {
        bankTab = 1, guildGuid = "42", profileId = "p-gs", generation = 1,
        source = "guildSupplies",
    }
    BankLog.requireBankReopenForFreshness = false
    BankLog:ProcessLogUpdate("slot_restore")
    assertEq(BankLog.lastFreshLogTab, 1, "successful update restores stamp after slot invalidate")
    assertEq(GS.IsBankContextSampleReady(1), true, "readiness restored after successful update")

    -- Slot change while a query is already outstanding: clear stamp, coalesce query.
    world.logQueries = {}
    BankLog.awaitingLogUpdate = true
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertEq(#world.logQueries, 0, "outstanding slots_changed does not start a second query")
    assertEq(BankLog.lastFreshLogTab, nil, "outstanding slots_changed clears stamp")
    assertEq(BankLog.awaitingLogUpdate, true, "outstanding query remains awaiting")
    assertEq(select(2, GS.IsBankContextSampleReady(1)), "log_pending",
        "outstanding slots_changed stays log_pending")

    -- Production CancelTimers clears stamp and awaiting.
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog.awaitingLogUpdate = true
    BankLog:CancelTimers("test_cancel")
    assertEq(BankLog.lastFreshLogTab, nil, "CancelTimers clears freshness stamp")
    assertEq(BankLog.awaitingLogUpdate, false, "CancelTimers clears awaiting")
    assertEq(GS.IsBankContextSampleReady(1), false, "CancelTimers leaves readiness unavailable")

    -- Denied / unknown tab access.
    BankLog.awaitingLogUpdate = false
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
