    -- Requested-item bounds: over-cap/invalid fixtures stay unavailable; valid max renders.
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    settleRoster()
    local createdBound, createdBoundStatus, createdBoundReason = GS:CreateStagedRecord()
    assertEq(createdBoundStatus, "accepted",
        "bounds fixture CreateStagedRecord: " .. tostring(createdBoundReason))
    assertTrue(createdBound ~= nil, "bounds fixture record created")
    startCampaign()
    local boundRec = GS:GetCurrentRecord()
    assertTrue(boundRec ~= nil, "bounds fixture current record available")
    local boundItems = boundRec.accounting._consumables.requestedItems
    local maxItems = (SF.Consumables and SF.Consumables.MAX_REQUESTED_ITEMS) or 256
    for i = 1, maxItems do
        boundItems[tostring(1000 + i)] = { itemId = 1000 + i, goal = i }
    end
    local okMax, errMax = GS.ValidateRequestedItemsMap(boundItems)
    assertEq(okMax, true, "valid maximum-sized map accepted")
    local copiedMax = GS:GetCampaignRequestedItems(boundRec.currentCampaignId)
    local copiedCount = 0
    for _ in pairs(copiedMax or {}) do copiedCount = copiedCount + 1 end
    assertEq(copiedCount, maxItems, "GetCampaignRequestedItems returns full max-sized map")
    local boundsPanel = makeRegion("Frame", "GSBoundsPanel", nil)
    boundsPanel:SetSize(600, 800)
    configPage:Build(boundsPanel)
    local maxRowCount
    for _, sec in ipairs((boundsPanel.__sfPageDef and boundsPanel.__sfPageDef.sections) or {}) do
        for _, item in ipairs(sec.items or {}) do
            if item.type == "consumableRequestedList" and type(item.getItems) == "function" then
                maxRowCount = #item.getItems()
            end
        end
    end
    assertEq(maxRowCount, maxItems, "UI constructs bounded rows for valid max-sized map")
    -- Over-cap: preserve SV unchanged and make record unavailable.
    boundItems[tostring(1000 + maxItems + 1)] = { itemId = 1000 + maxItems + 1, goal = 1 }
    local overflowSnapshot = {}
    for k, v in pairs(boundItems) do
        overflowSnapshot[k] = v
    end
    local overflowCount = 0
    for _ in pairs(boundItems) do overflowCount = overflowCount + 1 end
    assertTrue(overflowCount > maxItems, "fixture exceeds requested-item cap")
    assertEq(select(1, GS:GetCurrentRecord()), nil, "over-cap current map makes record unavailable")
    assertEq(select(2, GS:GetCurrentRecord()), "requested_items_overflow",
        "over-cap reason is requested_items_overflow")
    local afterCount = 0
    local preserved = true
    for k, v in pairs(overflowSnapshot) do
        afterCount = afterCount + 1
        if boundItems[k] ~= v then
            preserved = false
        end
    end
    assertEq(afterCount, overflowCount, "over-cap SV entry count preserved")
    assertEq(preserved, true, "over-cap SV entries preserved unchanged")
    configPage:Refresh(boundsPanel)
    local overflowRows = 0
    local overflowStatus
    for _, sec in ipairs((boundsPanel.__sfPageDef and boundsPanel.__sfPageDef.sections) or {}) do
        for _, item in ipairs(sec.items or {}) do
            if item.type == "consumableRequestedList" and type(item.getItems) == "function" then
                overflowRows = #item.getItems()
            end
            if item.type == "display" and type(item.get) == "function" and sec.id == "gsStatus"
                and (not overflowStatus) then
                overflowStatus = item.get()
            end
        end
    end
    assertEq(overflowRows, 0, "over-cap UI constructs no requested-item rows")
    assertTrue(type(overflowStatus) == "string" and overflowStatus ~= "",
        "over-cap presents unavailable status text")
    -- Prefer Unavailable when membership canRead is available; otherwise membership
    -- redaction may own the status row (shared details stay hidden).
    assertTrue(overflowStatus:find("Unavailable", 1, true)
        or overflowStatus:find("unavailable", 1, true)
        or overflowStatus:find("overflow", 1, true)
        or overflowStatus:find("membership", 1, true),
        "over-cap status row marks unavailable/redacted got=" .. tostring(overflowStatus))
    -- Invalid-heavy map: non-table rows fail closed (malformed, not truncated).
    boundItems[tostring(1000 + maxItems + 1)] = nil
    for i = 1, maxItems do
        boundItems[tostring(1000 + i)] = nil
    end
    for i = 1, maxItems + 5 do
        boundItems["bad-" .. i] = "not-a-row"
    end
    local badOk, badErr = GS.ValidateRequestedItemsMap(boundItems)
    assertEq(badOk, false, "invalid raw entries fail closed")
    assertEq(badErr, "requested_items_malformed", "non-table rows are malformed")
    assertEq(select(2, GS:GetCurrentRecord()), "requested_items_malformed",
        "invalid raw entries make record unavailable")
    for i = 1, maxItems + 5 do
        boundItems["bad-" .. i] = nil
    end

    -- In-cap malformed rows: reject/unavailable; preserve original retained state.
    local function assertMalformedReject(label, mutator)
        boundItems["42"] = { itemId = 42, goal = 3 }
        local baseline = GS:GetCurrentRecord()
        assertTrue(baseline ~= nil, label .. " baseline usable")
        local snapCampaign = baseline.currentCampaignId
        local snapOps = 0
        for _ in pairs(baseline.operations.records or {}) do snapOps = snapOps + 1 end
        local archiveCount = 0
        for _ in pairs(baseline.campaignArchives or {}) do
            archiveCount = archiveCount + 1
        end
        local snapRow = boundItems["42"]
        mutator(boundItems)
        local vok, verr = GS.ValidateRequestedItemsMap(boundItems)
        assertEq(vok, false, label .. " validation rejects")
        assertEq(verr, "requested_items_malformed", label .. " reason malformed")
        assertEq(select(1, GS:GetCurrentRecord()), nil, label .. " record unavailable")
        local opBad, prepSt = GS:NewCampaignOperation()
        assertEq(opBad, nil, label .. " New Campaign prepare blocked")
        assertEq(prepSt, "rejected", label .. " New Campaign prepare rejected")
        -- Restore original row; SV must still hold the mutated raw entry until we clear it.
        boundItems["42"] = snapRow
        local restored = GS:GetCurrentRecord()
        assertTrue(restored ~= nil, label .. " restored after clearing malformation")
        assertEq(restored.currentCampaignId, snapCampaign, label .. " current campaign unchanged")
        local opsAfter = 0
        for _ in pairs(restored.operations.records or {}) do opsAfter = opsAfter + 1 end
        assertEq(opsAfter, snapOps, label .. " operations unchanged")
        local archivesAfter = 0
        for _ in pairs(restored.campaignArchives or {}) do archivesAfter = archivesAfter + 1 end
        assertEq(archivesAfter, archiveCount, label .. " archives unchanged")
        assertEq(restored.accounting._consumables.requestedItems["42"].goal, 3,
            label .. " retained goal preserved")
    end
    assertMalformedReject("non-table", function(items)
        items["42"] = "not-a-row"
    end)
    assertMalformedReject("missing itemId", function(items)
        items["42"] = { goal = 3 }
    end)
    assertMalformedReject("invalid itemId", function(items)
        items["42"] = { itemId = 0, goal = 3 }
    end)
    assertMalformedReject("key/item mismatch", function(items)
        items["42"] = { itemId = 99, goal = 3 }
    end)
    assertMalformedReject("missing goal", function(items)
        items["42"] = { itemId = 42 }
    end)
    assertMalformedReject("negative goal", function(items)
        items["42"] = { itemId = 42, goal = -1 }
    end)
    assertMalformedReject("fractional goal", function(items)
        items["42"] = { itemId = 42, goal = 1.5 }
    end)
    local maxGoal = (SF.Consumables and SF.Consumables.MAX_GOAL) or 100000
    assertMalformedReject("over-max goal", function(items)
        items["42"] = { itemId = 42, goal = maxGoal + 1 }
    end)

    -- Canonical string keys only: numeric / mixed aliases fail closed (no collapse).
    boundItems["42"] = nil
    boundItems[42] = { itemId = 42, goal = 5 }
    assertEq(GS.ValidateRequestedItemsMap(boundItems), false,
        "numeric-only requested-item key rejected")
    assertEq(select(2, GS:GetCurrentRecord()), "requested_items_malformed",
        "numeric-only key makes record unavailable")
    boundItems[42] = nil
    boundItems["42"] = { itemId = 42, goal = 5 }
    boundItems[42] = { itemId = 42, goal = 9 }
    assertEq(GS.ValidateRequestedItemsMap(boundItems), false,
        "mixed numeric/string requested-item keys rejected")
    assertEq(select(2, GS:GetCurrentRecord()), "requested_items_malformed",
        "mixed-key map makes record unavailable")
    -- Prepare New Campaign on a clean canonical map, then corrupt keys before commit.
    boundItems[42] = nil
    boundItems["42"] = { itemId = 42, goal = 5 }
    local keyRec = GS:GetCurrentRecord()
    assertTrue(keyRec ~= nil, "canonical string key usable before corruption")
    local keyCamp = keyRec.currentCampaignId
    local keyOps = 0
    for _ in pairs(keyRec.operations.records or {}) do keyOps = keyOps + 1 end
    local keyArch = 0
    for _ in pairs(keyRec.campaignArchives or {}) do keyArch = keyArch + 1 end
    local keyOp = GS:NewCampaignOperation()
    assertTrue(keyOp ~= nil, "prepare New Campaign before key corruption")
    boundItems[42] = { itemId = 42, goal = 11 }
    local keySt, keyReason = GS:ApplyStagedCampaignOperation(keyOp)
    assertEq(keySt, "rejected", "commit rejects after mixed-key corruption")
    assertEq(keyReason, "requested_items_malformed",
        "commit revalidation surfaces requested_items_malformed")
    assertEq(SpectrumFederationDB.guildSupplies.guilds["club:42"].accounting._consumables.requestedItems[42].goal,
        11, "numeric alias row preserved on reject")
    assertEq(SpectrumFederationDB.guildSupplies.guilds["club:42"].accounting._consumables.requestedItems["42"].goal,
        5, "string key row preserved on reject")
    assertEq(SpectrumFederationDB.guildSupplies.guilds["club:42"].currentCampaignId, keyCamp,
        "campaign unchanged after key-collision reject")
    local keyOpsAfter = 0
    for _ in pairs(SpectrumFederationDB.guildSupplies.guilds["club:42"].operations.records or {}) do
        keyOpsAfter = keyOpsAfter + 1
    end
    assertEq(keyOpsAfter, keyOps, "operations unchanged after key-collision reject")
    local keyArchAfter = 0
    for _ in pairs(SpectrumFederationDB.guildSupplies.guilds["club:42"].campaignArchives or {}) do
        keyArchAfter = keyArchAfter + 1
    end
    assertEq(keyArchAfter, keyArch, "archives unchanged after key-collision reject")
    boundItems[42] = nil
    boundItems["42"] = { itemId = 42, goal = 3 }

    -- Malformed archive must not disable a usable current campaign.
    boundItems["42"] = { itemId = 42, goal = 3 }
    local usable = GS:GetCurrentRecord()
    assertTrue(usable ~= nil, "usable current restored after clearing overflow")
    local priorCampaignId = usable.currentCampaignId
    startCampaign() -- archives prior campaign with item 42
    usable = GS:GetCurrentRecord()
    assertTrue(usable.campaignArchives and usable.campaignArchives[priorCampaignId],
        "prior campaign archived on New Campaign")
    local archiveItems = usable.campaignArchives[priorCampaignId].requestedItems
    archiveItems["42"] = { itemId = 42, goal = -5 }
    local archivedItems, archiveErr = GS:GetCampaignRequestedItems(priorCampaignId)
    assertEq(archivedItems, nil, "malformed archive items unavailable")
    assertEq(archiveErr, "requested_items_malformed", "malformed archive reason")
    -- Also cover over-cap archive isolation.
    archiveItems["42"] = { itemId = 42, goal = 3 }
    for i = 1, maxItems + 2 do
        archiveItems[tostring(2000 + i)] = { itemId = 2000 + i, goal = 1 }
    end
    archivedItems, archiveErr = GS:GetCampaignRequestedItems(priorCampaignId)
    assertEq(archivedItems, nil, "over-cap archive items unavailable")
    assertEq(archiveErr, "requested_items_overflow", "over-cap archive reason")
    -- Current campaign remains readable after the bad archive mutation.
    usable.accounting._consumables.requestedItems["99"] = { itemId = 99, goal = 5 }
    local currentItems = GS:GetCampaignRequestedItems(usable.currentCampaignId)
    assertTrue(type(currentItems) == "table" and currentItems["99"] ~= nil,
        "usable current items survive bad archive")
    assertTrue(GS:GetCurrentRecord() ~= nil, "guild record still usable with bad archive")

    -- Configuration status area hierarchy (compact rows; no concatenated paragraph).
    local function statusAreaFrom(panel)
        local area = {
            statusGet = nil,
            campaignGet = nil,
            campaignVisible = nil,
            nextStepGet = nil,
            nextStepVisible = nil,
            warningGet = nil,
            warningVisible = nil,
        }
        for _, sec in ipairs((panel.__sfPageDef and panel.__sfPageDef.sections) or {}) do
            if sec.id == "gsStatus" then
                local helpIdx = 0
                for _, item in ipairs(sec.items or {}) do
                    if item.type == "display" and type(item.get) == "function" then
                        if not area.statusGet then
                            area.statusGet = item.get
                        elseif not area.campaignGet then
                            area.campaignGet = item.get
                            area.campaignVisible = item.visible
                        end
                    elseif item.type == "help" and type(item.getText) == "function" then
                        helpIdx = helpIdx + 1
                        if helpIdx == 1 then
                            area.nextStepGet = item.getText
                            area.nextStepVisible = item.visible
                        elseif helpIdx == 2 then
                            area.warningGet = item.getText
                            area.warningVisible = item.visible
                        end
                    end
                end
            end
        end
        return area
    end

    local function readArea(area)
        return {
            status = area.statusGet and area.statusGet() or nil,
            campaign = area.campaignGet and area.campaignGet() or nil,
            campaignShown = area.campaignVisible and area.campaignVisible() or false,
            nextStep = area.nextStepGet and area.nextStepGet() or nil,
            nextStepShown = area.nextStepVisible and area.nextStepVisible() or false,
            warning = area.warningGet and area.warningGet() or nil,
            warningShown = area.warningVisible and area.warningVisible() or false,
        }
    end

    local statusPanel = makeRegion("Frame", "GSStatusAreaPanel", nil)
    statusPanel:SetSize(420, 800)

    -- Not configured
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    configPage:Build(statusPanel)
    local area = statusAreaFrom(statusPanel)
    assertTrue(type(area.statusGet) == "function", "status UX: status display present")
    assertTrue(type(area.nextStepGet) == "function", "status UX: next-step help present")
    local view = readArea(area)
    assertEq(view.status, "Not configured", "status UX: not configured label")
    assertEq(view.campaignShown, false, "status UX: campaign hidden when not configured")
    assertEq(view.nextStepShown, true, "status UX: initialize next step shown")
    assertTrue(view.nextStep:find("Initialize Guild Supplies", 1, true),
        "status UX: initialize next step got=" .. tostring(view.nextStep))
    assertEq(view.warningShown, false, "status UX: no warning when not configured")

    -- Staged, no campaign: one next-step instruction, no repeated campaign wording.
    GS:CreateStagedRecord()
    view = readArea(area)
    assertEq(view.status, "Staged", "status UX: staged short label")
    assertEq(view.campaignShown, true, "status UX: campaign row when staged")
    assertEq(view.campaign, "Not started.", "status UX: campaign not started")
    assertEq(view.nextStepShown, true, "status UX: new-campaign next step shown")
    assertTrue(view.nextStep:find("Start a New Campaign", 1, true),
        "status UX: new-campaign next step got=" .. tostring(view.nextStep))
    assertTrue(not view.nextStep:find("Activation not ready", 1, true),
        "status UX: no duplicate activation-blocked campaign wording")
    assertTrue(not ((view.status or "") .. " " .. (view.nextStep or "")):find(
        "Start a New Campaign before adding items", 1, true),
        "status UX: no legacy no-campaign paragraph remnant")

    -- Staged campaign, bank tab unset
    startCampaign()
    local campId = GS:GetCurrentRecord().currentCampaignId
    GS:GetCurrentRecord().accounting._consumables.bankTab = nil
    view = readArea(area)
    assertEq(view.status, "Staged", "status UX: staged with campaign")
    assertEq(view.campaign, campId, "status UX: campaign id shown")
    assertTrue(view.nextStepShown and view.nextStep:find("Configure a Guild Bank tab", 1, true),
        "status UX: bank tab next step got=" .. tostring(view.nextStep))

    -- Bank log unavailable / pending / stale
    local tabOpStatus = GS:NewConfigOperation("set-bank-tab", "bankTab", 2)
    assertEq(GS:ApplyStagedConfigOperation(tabOpStatus), "accepted", "status UX: set bank tab")
    GS._BankContextReadinessProbe = function() return false, "log_pending" end
    view = readArea(area)
    assertTrue(view.nextStepShown and (
        view.nextStep:find("become available", 1, true)
        or view.nextStep:find("fresh transaction-log sample", 1, true)),
        "status UX: log pending next step got=" .. tostring(view.nextStep))
    GS._BankContextReadinessProbe = function() return false, "log_stale" end
    view = readArea(area)
    assertTrue(view.nextStepShown and view.nextStep:find("stale", 1, true),
        "status UX: log stale next step got=" .. tostring(view.nextStep))
    GS._BankContextReadinessProbe = function() return false, "bank_closed" end
    view = readArea(area)
    assertTrue(view.nextStepShown and view.nextStep:find("Open the Guild Bank", 1, true),
        "status UX: bank closed next step got=" .. tostring(view.nextStep))

    -- Ready to activate / successfully activated (inline bank sample; helpers are defined later).
    GetNumGuildBankTransactions = function() return 0 end
    GetGuildBankTransaction = function()
        return "deposit", "Donor-Garona", "|Hitem:9100::::::::|h[Flask]|h", 2,
            1, 1, 2026, 10, 19, 12
    end
    GS._BankContextReadinessProbe = function() return true end
    view = readArea(area)
    assertEq(view.status, "Staged", "status UX: still staged when ready")
    assertTrue(view.nextStepShown and view.nextStep:find("Activate Guild Supplies", 1, true),
        "status UX: activate-ready next step got=" .. tostring(view.nextStep))
    assertTrue(view.nextStep:find("Guild Bank", 1, true),
        "status UX: activate-ready mentions Guild Bank")
    assertEq(view.warningShown, false, "status UX: no warning when ready")
    local _, actStatusUx = GS:ActivateCanonicalDataset()
    assertEq(actStatusUx, "accepted", "status UX: activate accepted")
    view = readArea(area)
    assertTrue(type(view.status) == "string" and view.status:find("Live", 1, true),
        "status UX: live status got=" .. tostring(view.status))
    assertTrue(view.status:find("cutover", 1, true),
        "status UX: live status names cutover authority")
    assertEq(view.nextStepShown, false, "status UX: no next step when live and healthy")
    assertEq(view.warningShown, false, "status UX: no warning when live and healthy")
    GetNumGuildBankTransactions = nil
    GetGuildBankTransaction = nil
    GS._BankContextReadinessProbe = nil

    -- Dataset conflict / adoption pending warnings stay distinct from next step.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    assertEq(select(2, GS:CreateStagedRecord()), "accepted", "status UX: mismatch fixture create")
    startCampaign()
    local tabOpMismatch = GS:NewConfigOperation("set-bank-tab", "bankTab", 2)
    assertEq(GS:ApplyStagedConfigOperation(tabOpMismatch), "accepted", "status UX: mismatch fixture tab")
    statusPanel = makeRegion("Frame", "GSStatusAreaPanel2", nil)
    statusPanel:SetSize(420, 800)
    configPage:Build(statusPanel)
    area = statusAreaFrom(statusPanel)
    local priorMismatch = GS.GetDatasetMismatchState
    GS.GetDatasetMismatchState = function()
        return {
            blocked = true,
            peers = { { peerName = "Bob-Garona", datasetId = "peer-ds-1" } },
        }
    end
    view = readArea(area)
    assertEq(view.warningShown, true, "status UX: mismatch warning visible")
    assertTrue(view.warning:find("Bob-Garona", 1, true) and view.warning:find("peer-ds-1", 1, true),
        "status UX: mismatch warning names peer got=" .. tostring(view.warning))
    assertTrue(not (view.nextStepShown and view.nextStep
        and view.nextStep:find("different staged dataset", 1, true)),
        "status UX: mismatch text is not duplicated into next step")
    GS.GetDatasetMismatchState = priorMismatch

    local priorAdop = GS.GetPendingAdoption
    GS.GetPendingAdoption = function()
        return { sourceDatasetId = "adopt-ds", sourcePeer = "Carol-Garona", ready = false }
    end
    view = readArea(area)
    assertEq(view.warningShown, true, "status UX: adoption warning visible")
    assertTrue(view.warning:find("Adoption in progress", 1, true)
        and view.warning:find("Carol-Garona", 1, true),
        "status UX: adoption warning got=" .. tostring(view.warning))
    assertTrue(not (view.nextStepShown and view.nextStep
        and view.nextStep:find("Adoption in progress", 1, true)),
        "status UX: adoption pending not duplicated into next step")
    GS.GetPendingAdoption = priorAdop

    -- Membership / read access unavailable: redact campaign; hide next step/warnings.
    local priorMembersUx = world.guild.members
    world.guild.members = {}
    settleRoster()
    view = readArea(area)
    assertTrue(type(view.status) == "string" and view.status:find("membership", 1, true),
        "status UX: membership pending in status row got=" .. tostring(view.status))
    assertEq(view.campaignShown, false, "status UX: campaign hidden without canRead")
    assertEq(view.nextStepShown, false, "status UX: next step hidden without canRead")
    assertEq(view.warningShown, false, "status UX: warnings hidden without canRead")
    world.guild.members = priorMembersUx
    settleRoster()

    -- Narrow width + repeated Refresh remain stable.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    statusPanel = makeRegion("Frame", "GSStatusAreaPanel3", nil)
    statusPanel:SetSize(280, 800)
    configPage:Build(statusPanel)
    area = statusAreaFrom(statusPanel)
    local firstUx = readArea(area)
    for _ = 1, 25 do
        configPage:Refresh(statusPanel)
    end
    local lastUx = readArea(area)
    assertEq(lastUx.status, firstUx.status, "status UX: status stable across refreshes")
    assertEq(lastUx.campaign, firstUx.campaign, "status UX: campaign stable across refreshes")
    assertEq(lastUx.nextStep, firstUx.nextStep, "status UX: next step stable across refreshes")
    assertEq(lastUx.warningShown, firstUx.warningShown, "status UX: warning visibility stable")
    assertTrue(type(lastUx.nextStep) == "string" and lastUx.nextStep:find("Next step:", 1, true),
        "status UX: next step remains a single prefixed line")
    local _, nextCountUx = lastUx.nextStep:gsub("Next step:", "Next step:")
    assertEq(nextCountUx, 1, "status UX: next step prefix not multiplied by refresh")
    assertEq(#world.chat, 0, "status UX: no chat")
    GetNumGuildBankTransactions = nil
    GetGuildBankTransaction = nil
    GS._BankContextReadinessProbe = nil

    -----------------------------------------------------------------------
    -- Disabled-control explanatory tooltips (Configuration + Logs)
    -- Nested function keeps locals under Lua 5.1's 200-local main limit.
    -----------------------------------------------------------------------
    local function runDisabledTooltipTests()
    local tipLog = { owner = nil, title = nil, lines = {}, shown = false }
    local realTooltip = GameTooltip
    GameTooltip = {
        Hide = function()
            tipLog.shown = false
            tipLog.owner = nil
            tipLog.title = nil
            tipLog.lines = {}
        end,
        SetOwner = function(_, owner)
            tipLog.owner = owner
        end,
        SetText = function(_, title)
            tipLog.title = title
            tipLog.lines = {}
        end,
        AddLine = function(_, text)
            tipLog.lines[#tipLog.lines + 1] = text
        end,
        Show = function()
            tipLog.shown = true
        end,
    }

    local function findDefItem(panel, pred)
        for _, sec in ipairs((panel.__sfPageDef and panel.__sfPageDef.sections) or {}) do
            for _, item in ipairs(sec.items or {}) do
                if pred(item) then
                    return item
                end
            end
        end
        return nil
    end

    local function findButtonByText(node, needle, out)
        if node.kind == "Button" and node.text and tostring(node.text):find(needle, 1, true) then
            out[#out + 1] = node
        end
        for _, child in ipairs(node.children or {}) do
            findButtonByText(child, needle, out)
        end
    end

    local function fireEnter(region)
        local script = region.scripts and region.scripts.OnEnter
        if script then
            script(region)
        end
    end

    local function fireLeave(region)
        local script = region.scripts and region.scripts.OnLeave
        if script then
            script(region)
        end
    end

    -- Fresh not-configured: Initialize tip distinguishes already-init vs need-rank.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    settleRoster()
    local tipPanel = makeRegion("Frame", "GSDisabledTipPanel", nil)
    tipPanel:SetSize(600, 900)
    configPage:Build(tipPanel)
    local initItem = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Initialize", 1, true)
    end)
    assertTrue(initItem and type(initItem.getDisabledTooltip) == "function",
        "disabled tip: Initialize exposes getDisabledTooltip")
    assertEq(initItem.enabled and initItem.enabled(), true,
        "disabled tip: ordinary Initialize enabled")
    assertNil(initItem.getDisabledTooltip(),
        "disabled tip: Initialize tip nil while enabled")

    local activateItem = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Activate", 1, true)
    end)
    assertTrue(activateItem and type(activateItem.getDisabledTooltip) == "function",
        "disabled tip: Activate exposes getDisabledTooltip")
    assertEq(activateItem.enabled and activateItem.enabled(), false,
        "disabled tip: Activate disabled before campaign")
    local actTip = activateItem.getDisabledTooltip()
    assertTrue(type(actTip) == "string" and actTip:find("Initialize", 1, true),
        "disabled tip: Activate asks for Initialize when not configured got=" .. tostring(actTip))
    assertTrue(not actTip:find("Guild Bank", 1, true),
        "disabled tip: Activate does not require open bank before init/campaign")

    local bankItem = findDefItem(tipPanel, function(item)
        return item.type == "dropdown" and item.label
            and tostring(item.label):find("Bank Tab", 1, true)
    end)
    assertTrue(bankItem and type(bankItem.getDisabledTooltip) == "function",
        "disabled tip: Bank Tab exposes getDisabledTooltip")
    local bankTip = bankItem.getDisabledTooltip()
    assertTrue(type(bankTip) == "string" and bankTip:find("Initialize", 1, true),
        "disabled tip: Bank Tab needs init got=" .. tostring(bankTip))
    assertTrue(not bankTip:find("Guild Bank", 1, true),
        "disabled tip: Bank Tab tip must not require opening the Guild Bank before init")

    -- Overlay hover on a disabled Activate button shows the tip without enabling.
    local activateBtns = {}
    findButtonByText(tipPanel, "Activate", activateBtns)
    assertTrue(#activateBtns >= 1, "disabled tip: Activate button widget present")
    local actBtn = activateBtns[1]
    assertEq(actBtn.enabled, false, "disabled tip: Activate widget remains disabled")
    configPage:Refresh(tipPanel)
    findButtonByText(tipPanel, "Activate", activateBtns)
    actBtn = activateBtns[#activateBtns] or actBtn
    local overlay = actBtn.__sfDisabledTipOverlay
    assertTrue(overlay ~= nil, "disabled tip: overlay created for disabled Activate")
    assertEq(overlay.__sfMouseCatching, true, "disabled tip: overlay catches mouse while disabled")
    assertEq(overlay.mouseEnabled, true, "disabled tip: overlay EnableMouse(true) while disabled")
    tipLog.shown = false
    fireEnter(overlay)
    assertEq(tipLog.shown, true, "disabled tip: hover shows GameTooltip")
    assertTrue(type(tipLog.lines[1]) == "string" and tipLog.lines[1]:find("Initialize", 1, true),
        "disabled tip: hover body matches Activate tip got=" .. tostring(tipLog.lines[1]))
    fireLeave(overlay)
    assertEq(tipLog.shown, false, "disabled tip: leave hides GameTooltip")
    -- Overlay must not make the button clickable.
    actBtn:Click()
    assertNil(select(1, GS:GetCurrentRecord()),
        "disabled tip: clicking disabled Activate does nothing")

    -- After Initialize + campaign without bank tab: tip updates to bank-tab guidance.
    assertEq(select(2, GS:CreateStagedRecord()), "accepted", "disabled tip: initialize for activate tips")
    startCampaign()
    configPage:Refresh(tipPanel)
    activateItem = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Activate", 1, true)
    end)
    actTip = activateItem.getDisabledTooltip()
    assertTrue(type(actTip) == "string"
            and (actTip:find("bank tab", 1, true) or actTip:find("Bank tab", 1, true)
                or actTip:find("Guild Bank tab", 1, true)),
        "disabled tip: Activate asks for bank tab after campaign got=" .. tostring(actTip))
    assertTrue(actTip:find("do not require the bank to be open", 1, true)
            or actTip:find("Configure a Guild Bank tab", 1, true),
        "disabled tip: bank-tab guidance keeps campaign/init bank-open free got=" .. tostring(actTip))

    -- Unauthorized member: permission tip takes priority; no guild config leakage.
    local priorMembersTip = world.guild.members
    world.guild.members = {
        { name = "Alice-Garona", guid = "Player-1-Alice", rankOrder = 5 },
    }
    settleRoster()
    configPage:Refresh(tipPanel)
    activateItem = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Activate", 1, true)
    end)
    actTip = activateItem.getDisabledTooltip()
    assertTrue(type(actTip) == "string" and actTip:find("rank does not permit", 1, true),
        "disabled tip: unauthorized Activate tip got=" .. tostring(actTip))
    assertTrue(not actTip:find("bank tab", 1, true) and not actTip:find("campaign", 1, true),
        "disabled tip: unauthorized tip does not leak config prerequisites")
    local itemsItem = findDefItem(tipPanel, function(item)
        return item.type == "editboxButton" and item.label
            and tostring(item.label):find("Add item", 1, true)
    end)
    local itemsTip = itemsItem.getDisabledTooltip()
    assertTrue(type(itemsTip) == "string" and itemsTip:find("rank does not permit", 1, true),
        "disabled tip: unauthorized items tip got=" .. tostring(itemsTip))
    world.guild.members = priorMembersTip
    settleRoster()

    -- Adoption / conflict tips when no sources / no conflicts.
    configPage:Refresh(tipPanel)
    local adoptSource = findDefItem(tipPanel, function(item)
        return item.type == "dropdown" and item.label
            and tostring(item.label):find("Source dataset", 1, true)
    end)
    local adoptTip = adoptSource.getDisabledTooltip()
    assertTrue(type(adoptTip) == "string" and adoptTip:find("No eligible peer", 1, true),
        "disabled tip: adoption source empty got=" .. tostring(adoptTip))
    local adoptBegin = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Start adoption", 1, true)
    end)
    assertTrue(adoptBegin.getDisabledTooltip():find("No eligible peer", 1, true)
            or adoptBegin.getDisabledTooltip():find("Select a source", 1, true),
        "disabled tip: start adoption blocked without source")
    local adoptCancel = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Cancel adoption", 1, true)
    end)
    assertEq(adoptCancel.getDisabledTooltip(),
        "There is no adoption in progress.",
        "disabled tip: cancel adoption when idle")
    local conflictOpen = findDefItem(tipPanel, function(item)
        return item.type == "dropdown" and item.label
            and tostring(item.label):find("Open conflict", 1, true)
    end)
    assertTrue(conflictOpen.getDisabledTooltip():find("no unresolved", 1, true)
            or conflictOpen.getDisabledTooltip():find("no unresolved configuration", 1, true)
            or conflictOpen.getDisabledTooltip():find("There are no unresolved", 1, true),
        "disabled tip: open conflict none got=" .. tostring(conflictOpen.getDisabledTooltip()))
    local conflictChoose = findDefItem(tipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Use this value", 1, true)
    end)
    assertTrue(conflictChoose.getDisabledTooltip():find("no unresolved", 1, true)
            or conflictChoose.getDisabledTooltip():find("Select an open", 1, true),
        "disabled tip: use-this-value without selection")

    -- Small-guild init: need explicit rank before Initialize enables.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Member" }
    settleRoster()
    local smallTipPanel = makeRegion("Frame", "GSDisabledTipSmall", nil)
    smallTipPanel:SetSize(600, 800)
    configPage:Build(smallTipPanel)
    initItem = findDefItem(smallTipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Initialize", 1, true)
    end)
    assertEq(initItem.enabled and initItem.enabled(), true,
        "disabled tip: small-guild Initialize uses the shared officer policy")
    local smallTip = initItem.getDisabledTooltip()
    assertTrue(smallTip == nil or not tostring(smallTip):find("editor rank", 1, true),
        "disabled tip: small-guild Initialize does not ask for an editor rank got="
            .. tostring(smallTip))

    -- Already initialized: Initialize tip says already done.
    assertEq(select(2, GS:CreateStagedRecord(2)), "accepted", "disabled tip: small init")
    configPage:Refresh(smallTipPanel)
    initItem = findDefItem(smallTipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Initialize", 1, true)
    end)
    assertEq(initItem.enabled and initItem.enabled(), false,
        "disabled tip: Initialize disabled after init")
    assertTrue(initItem.getDisabledTooltip():find("already been initialized", 1, true),
        "disabled tip: already initialized got=" .. tostring(initItem.getDisabledTooltip()))

    -- Logs: campaign/history pagination tips + membership privacy.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    settleRoster()
    GS:CreateStagedRecord()
    startCampaign()
    local logsTipPanel = makeRegion("Frame", "GSDisabledTipLogs", nil)
    logsTipPanel:SetSize(600, 800)
    logsPage:Build(logsTipPanel)
    local newerItem = findDefItem(logsTipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Newer", 1, true)
    end)
    local olderItem = findDefItem(logsTipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Older", 1, true)
    end)
    assertTrue(newerItem and olderItem, "disabled tip: Newer/Older defs present")
    assertTrue(newerItem.getDisabledTooltip():find("first page", 1, true),
        "disabled tip: Newer on first page got=" .. tostring(newerItem.getDisabledTooltip()))
    assertTrue(olderItem.getDisabledTooltip():find("last page", 1, true),
        "disabled tip: Older on last/empty page got=" .. tostring(olderItem.getDisabledTooltip()))

    local campItem = findDefItem(logsTipPanel, function(item)
        return item.type == "dropdown" and item.label
            and tostring(item.label):find("Campaign", 1, true)
            and item.getDisabledTooltip
    end)
    assertTrue(campItem ~= nil, "disabled tip: Logs campaign dropdown present")
    -- With a campaign, dropdown should be enabled → tip nil.
    assertEq(campItem.enabled and campItem.enabled(), true,
        "disabled tip: campaign select enabled with campaign")
    assertNil(campItem.getDisabledTooltip(),
        "disabled tip: campaign select tip nil while enabled")

    -- Unverified membership: logs tips stay membership-only.
    world.guild.members = {}
    settleRoster()
    logsPage:Refresh(logsTipPanel)
    campItem = findDefItem(logsTipPanel, function(item)
        return item.type == "dropdown" and item.label
            and tostring(item.label):find("Campaign", 1, true)
            and item.getDisabledTooltip
    end)
    local campTip = campItem.getDisabledTooltip()
    assertTrue(type(campTip) == "string" and campTip:find("verified membership", 1, true),
        "disabled tip: logs campaign membership tip got=" .. tostring(campTip))
    newerItem = findDefItem(logsTipPanel, function(item)
        return item.type == "button" and item.buttonText
            and tostring(item.buttonText):find("Newer", 1, true)
    end)
    assertTrue(newerItem.getDisabledTooltip():find("verified membership", 1, true),
        "disabled tip: Newer membership tip")
    world.guild.members = priorMembersTip
    settleRoster()

    -- Repeated refresh must not accumulate overlays/handlers (one overlay per widget).
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    local refreshTipPanel = makeRegion("Frame", "GSDisabledTipRefresh", nil)
    refreshTipPanel:SetSize(600, 800)
    configPage:Build(refreshTipPanel)
    local createdBefore = #created
    for _ = 1, 40 do
        configPage:Refresh(refreshTipPanel)
    end
    local activateRefresh = {}
    findButtonByText(refreshTipPanel, "Activate", activateRefresh)
    assertTrue(#activateRefresh >= 1, "disabled tip: activate present after refresh loop")
    local ov = activateRefresh[1].__sfDisabledTipOverlay
    assertTrue(ov ~= nil, "disabled tip: overlay survives refresh")
    -- Overlay is created once; refreshes must not spawn unbounded Frame children.
    assertTrue((#created - createdBefore) < 80,
        "disabled tip: refresh does not accumulate frames grew="
            .. tostring(#created - createdBefore))
    -- Re-enter after refresh still works with one handler.
    tipLog.shown = false
    fireEnter(ov)
    assertEq(tipLog.shown, true, "disabled tip: hover still works after many refreshes")
    fireLeave(ov)

    -- Enabled New Campaign (after init) must not leave a catching overlay.
    assertEq(select(2, GS:CreateStagedRecord()), "accepted", "disabled tip: init for enabled overlay")
    configPage:Refresh(refreshTipPanel)
    local newCampBtns = {}
    findButtonByText(refreshTipPanel, "New Campaign", newCampBtns)
    assertTrue(#newCampBtns >= 1, "disabled tip: New Campaign button present")
    local nc = newCampBtns[1]
    assertEq(nc.enabled, true, "disabled tip: New Campaign enabled with record")
    local ncOverlay = nc.__sfDisabledTipOverlay
    if ncOverlay then
        assertEq(ncOverlay.__sfMouseCatching, false,
            "disabled tip: enabled control overlay does not catch mouse")
        assertEq(ncOverlay.mouseEnabled, false,
            "disabled tip: enabled control overlay EnableMouse(false)")
    end
    local ncItem = findDefItem(refreshTipPanel, function(item)
        return item.type == "button" and item.buttonText == "New Campaign"
    end)
    assertTrue(ncItem ~= nil, "disabled tip: New Campaign def present")
    assertTrue(type(ncItem.tooltip) == "string"
            and ncItem.tooltip:find("archived and can be viewed in Logs", 1, true),
