    assertEq(GS:GetCurrentRecord().accounting._consumables.requestedItems[victimKey], nil,
        "3A27: fit removal applied")
    assertEq(GS:GetCurrentRecord().accounting._consumables.requestedItems["42422"].goal, 5,
