do
    -- 3C28) B2: freshness age gate; stale blocks; fresh/empty/pending/cancel paths.
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    resetDb()
    initGS()
    GS:CreateStagedRecord()
    startCampaign()
    assertEq(GS:ApplyStagedConfigOperation(
        GS:NewConfigOperation("set-bank-tab", "bankTab", 1)), "accepted", "3C28: tab")
    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    GS._BankContextReadinessProbe = nil
    world.bankTabInfo = { [1] = { name = "Supplies", isViewable = true } }
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    BankLog.bankOpen = true
    BankLog.awaitingLogUpdate = false
    BankLog.activeContext = {
        bankTab = 1, guildGuid = "42", sampleOnly = true,
        generation = 1, requestedSet = {}, observedBy = "Alice-Garona",
    }
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogGuild = "42"
    BankLog.lastFreshLogAt = world.time
    assertEq(GS.IsBankContextSampleReady(1), true, "3C28: fresh ready")
    world.time = world.time + (GS.MAX_BANK_SAMPLE_AGE_SECONDS or 120) + 1
    local staleReady, staleReason = GS.IsBankContextSampleReady(1)
    assertEq(staleReady, false, "3C28: stale not ready")
    assertEq(staleReason, "log_stale", "3C28: log_stale reason")
    local guidance = GS.FormatActivationGuidance({
        canActivate = false, reason = "log_stale", bankReason = "log_stale",
    })
    assertTrue(type(guidance) == "string" and guidance:find("stale", 1, true),
        "3C28: stale guidance actionable")
    BankLog.lastFreshLogAt = world.time
    assertEq(GS.IsBankContextSampleReady(1), true, "3C28: re-stamp restores ready")
    BankLog.awaitingLogUpdate = true
    assertEq(select(2, GS.IsBankContextSampleReady(1)), "log_pending", "3C28: in-progress")
    BankLog.awaitingLogUpdate = false
    BankLog.lastFreshLogTab = nil
    BankLog.lastFreshLogAt = nil
    assertEq(select(2, GS.IsBankContextSampleReady(1)), "log_not_updated", "3C28: missing stamp")
    BankLog.bankOpen = false
    BankLog.lastFreshLogTab = 1
    BankLog.lastFreshLogAt = world.time
    assertEq(select(2, GS.IsBankContextSampleReady(1)), "bank_closed", "3C28: bank closed")
    GetGuildBankTabInfo = nil
    disarmFreshBankSample()
    assertEq(#world.chat, 0, "3C28: no chat")
end

do
    -- 3C29) C: per-witness pending quota + reserved local capacity; honest deposit still credits.
    local record = seedActivatableCampaign(9129, 200)
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    local _, st = GS:ActivateCanonicalDataset()
    assertEq(st, "accepted", "3C29: activate")
    record = GS:GetCurrentRecord()
    world.time = (tonumber(record.liveCutover.contextObservedAt) or world.time) + 7200
    ensureNonOfficerRoster()
    GS:EnsureGossipProvider()
    local perWitness = GS.MAX_PENDING_EVIDENCE_PER_WITNESS or 32
    local reserved = GS.RESERVED_LOCAL_PENDING_EVIDENCE or 16
    local flooded = 0
    local blocked = 0
    for n = 1, perWitness + 20 do
        local evidence = makeDepositEvidence(record, {
            itemId = 9129, quantity = 1,
            donor = "Flood" .. n .. "-Garona",
            occurrenceIndex = n,
            neighborsOlder = { "older|flood|" .. n },
            neighborsNewer = { "newer|flood|" .. n },
            observedAt = world.time + n,
        })
        local body = {
            kind = "gs-evidence",
            datasetId = record.datasetId,
            campaignId = record.currentCampaignId,
            evidence = evidence,
        }
        local stE, reasonE = providerApply(body, "Dave-Garona")
        if stE == "pending" or stE == "accepted" then
            flooded = flooded + 1
        elseif stE == "rejected" and (reasonE == "witness_quota" or reasonE == "full") then
            blocked = blocked + 1
        end
    end
    assertTrue(flooded <= perWitness, "3C29: flood bounded by per-witness quota flooded="
        .. tostring(flooded))
    assertTrue(blocked >= 1, "3C29: further flood rejected")
    -- Local observation still has reserved capacity.
    local honest = makeDepositEvidence(record, {
        itemId = 9129, quantity = 7, donor = "Honest-Garona",
        occurrenceIndex = 9001,
        neighborsOlder = { "older|honest" },
        neighborsNewer = { "newer|honest" },
    })
    for _, pair in ipairs({
        { "Player-1-Eve", "Eve-Garona" },
        { "Player-1-Frank", "Frank-Garona" },
        { "Player-1-Grace", "Grace-Garona" },
    }) do
        local stH, rH = GS:_AdmitObservationForTests(honest, pair[1], pair[2])
        assertTrue(stH == "accepted" or stH == "pending" or stH == "duplicate",
            "3C29: honest admit st=" .. tostring(stH) .. " r=" .. tostring(rH))
    end
    assertEq(tonumber(GS:ProjectCampaignProgress(record.currentCampaignId).itemTotals[9129]) or 0, 7,
        "3C29: honest three-witness deposit credits after flood")
    -- Duplicate replay of flooded body stays bounded.
    local replaySt = providerApply({
        kind = "gs-evidence",
        datasetId = record.datasetId,
        campaignId = record.currentCampaignId,
        evidence = makeDepositEvidence(record, {
            itemId = 9129, quantity = 1, donor = "Flood1-Garona",
            occurrenceIndex = 1,
            neighborsOlder = { "older|flood|1" },
            neighborsNewer = { "newer|flood|1" },
            observedAt = world.time + 1,
        }),
    }, "Dave-Garona")
    assertTrue(replaySt == "pending" or replaySt == "duplicate" or replaySt == "rejected",
        "3C29: replay bounded st=" .. tostring(replaySt))
    simulateRuntimeReload()
    assertEq(tonumber(GS:ProjectCampaignProgress(GS:GetCurrentRecord().currentCampaignId)
        .itemTotals[9129]) or 0, 7, "3C29: credit durable after reload")
    assertTrue((GS.MAX_PENDING_EVIDENCE or 128) - reserved >= perWitness,
        "3C29: reserved headroom coherent")
    disarmFreshBankSample()
    assertEq(#world.chat, 0, "3C29: no chat")
end

do
    -- 3C30) D1: archived history remains inspectable with uncredited labels.
    local record = seedActivatableCampaign(9130, 30)
    local camp1 = record.currentCampaignId
    local gen1 = record.accounting._consumables.generation
    record.accounting._consumableEvents[#record.accounting._consumableEvents + 1] = {
        id = "ctx:gs:arch-staged",
        txnId = "ctx:gs:arch-staged",
        type = "donation",
        itemId = 9130,
        quantity = 6,
        actor = "ArchStaged-Garona",
        generation = gen1,
        timestamp = world.time,
        campaignId = camp1,
        datasetId = record.datasetId,
        coreSignature = "deposit|ArchStaged-Garona|9130|6",
        verification = "witnesses",
        gsProductionCredit = false,
    }
    -- Archive via New Campaign, then activate.
    local campOp = GS:NewCampaignOperation()
    assertEq(GS:ApplyStagedCampaignOperation(campOp), "accepted", "3C30: archive prior campaign")
    record = GS:GetCurrentRecord()
    assertTrue(record.campaignArchives[camp1] ~= nil, "3C30: archive present")
    armFreshBankSample(true)
    local _, st = GS:ActivateCanonicalDataset()
    assertEq(st, "accepted", "3C30: activate after archive")
    record = GS:GetCurrentRecord()
    assertEq(tonumber(GS:ProjectCampaignProgress(camp1).itemTotals[9130]) or 0, 0,
        "3C30: archived uncredited not in live progress")
    local rows, total = GS:ListCampaignHistory(camp1, 20, 0)
    assertTrue(total >= 1, "3C30: archived history visible total=" .. tostring(total))
    local found = false
    for i = 1, #rows do
        if rows[i].id == "ctx:gs:arch-staged" then
            found = true
            assertTrue(rows[i].uncredited == true, "3C30: uncredited flag")
            assertTrue((rows[i].text or ""):find("uncredited", 1, true),
                "3C30: uncredited label in text")
            break
        end
    end
    assertTrue(found, "3C30: staged archived row inspectable")

    -- Legitimate post-activation archived history still displays without uncredited label.
    local camp2 = record.currentCampaignId
    assertEq(GS:ApplyStagedConfigOperation(GS:NewConfigOperation("set-requested-item", {
        itemId = 9130,
    }, { itemId = 9130, goal = 30, removed = false })), "accepted", "3C30: item on live campaign")
    world.time = (tonumber(record.liveCutover.contextObservedAt) or world.time) + 7200
    local clear = makeDepositEvidence(record, {
        itemId = 9130, quantity = 3, donor = "ArchLive-Garona",
        observedAt = world.time, ageHours = 0,
        occurrenceIndex = 1,
        neighborsOlder = { "older|archlive" },
        neighborsNewer = { "newer|archlive" },
    })
    for _, pair in ipairs({
        { "Player-1-Alice", "Alice-Garona" },
        { "Player-1-Bob", "Bob-Garona" },
        { "Player-1-Carol", "Carol-Garona" },
    }) do
        GS:_AdmitObservationForTests(clear, pair[1], pair[2])
    end
    assertEq(tonumber(GS:ProjectCampaignProgress(camp2).itemTotals[9130]) or 0, 3,
        "3C30: live credit before second archive")
    local campOp2 = GS:NewCampaignOperation()
    assertEq(GS:ApplyStagedCampaignOperation(campOp2), "accepted", "3C30: archive live campaign")
    local liveRows = GS:ListCampaignHistory(camp2, 20, 0)
    local liveFound = false
    for i = 1, #(liveRows or {}) do
        if liveRows[i].id and (liveRows[i].text or ""):find("ArchLive", 1, true) then
            liveFound = true
            assertTrue(liveRows[i].uncredited ~= true, "3C30: credited archived row not labeled")
            break
        end
    end
    assertTrue(liveFound, "3C30: credited archived history visible")
    disarmFreshBankSample()
    assertEq(#world.chat, 0, "3C30: no chat")
end

do
    -- 3C31) A2 provenance: staged post-cutover adjustment must not launder into
    -- live credit via activation export or unmarked remote gs-op (#389).
    local alice = seedActivatableCampaign(9131, 40)
    local _, stAct = GS:ActivateCanonicalDataset()
    assertEq(stAct, "accepted", "3C31: alice activates")
    alice = GS:GetCurrentRecord()
    local cutover = alice.liveCutover
    local marker = cutover.cutoverMarker
    local cutTs = tonumber(cutover.contextObservedAt)
    local datasetId = alice.datasetId
    local campaignId = alice.currentCampaignId
    local permission = alice.permission
    local aliceSnapshot = alice
    local descBody = {
        kind = "dataset-desc",
        schemaVersion = 1,
        guildKey = "club:42",
        datasetId = datasetId,
        editorRankPosition = 3,
        permissionRevisionId = permission.revisionId,
        activation = GS.ACTIVATION_ACTIVE,
        cutoverMarker = marker,
        liveCutover = GS.DescribeLiveCutover(cutover),
        currentCampaignId = campaignId,
    }

    local function seedStagedSameDataset(name, guid, rank)
        local srcCons = aliceSnapshot.accounting._consumables
        local cons = {
            guild = srcCons.guild,
            bankTab = srcCons.bankTab,
            requestedItems = {},
            generation = srcCons.generation,
            configSeq = srcCons.configSeq,
            eventSeq = 0,
            txnRegistry = {},
            eligibility = {
                baselineEstablished = true,
                baselineAt = cutTs - 100,
                tabEligibleFrom = cutTs - 100,
                items = {},
            },
        }
        if type(srcCons.requestedItems) == "table" then
            for ik, iv in pairs(srcCons.requestedItems) do
                if type(iv) == "table" then
                    local copy = {}
                    for fk, fv in pairs(iv) do copy[fk] = fv end
                    cons.requestedItems[ik] = copy
                else
                    cons.requestedItems[ik] = iv
                end
            end
        end
        SpectrumFederationDB = {
            guildSupplies = {
                schemaVersion = 1,
                localWriter = { nonce = "ffffffffffffffffffffffff", nextSeq = 1 },
                guilds = {
                    ["club:42"] = {
                        schemaVersion = 1,
                        activation = GS.ACTIVATION_STAGED,
                        datasetId = datasetId,
                        permission = permission,
                        currentCampaignId = campaignId,
                        campaigns = aliceSnapshot.campaigns,
                        campaignArchives = aliceSnapshot.campaignArchives or {},
                        campaignContext = aliceSnapshot.campaignContext or {},
                        accounting = {
                            schemaVersion = 1,
                            _consumables = cons,
                            _consumableEvents = {},
                            _consumableEventArchive = {},
                            _mutationSeq = 1,
                        },
                        observations = {
                            byCampaign = {
                                [campaignId] = {
                                    schemaVersion = 1, seq = 0, scopes = {}, pending = {},
                                },
                            },
                        },
                        identityLinks = aliceSnapshot.identityLinks,
                        operations = {
                            schemaVersion = 1,
                            order = {}, records = {}, heads = {},
                            pending = {}, conflicts = {}, openConflicts = {},
                        },
                        confirmationRefs = {},
                    },
                },
            },
        }
        setPlayer(name .. "-Garona", guid, rank)
        switchPlayer(name, guid, rank)
        GS._root = nil
        GS._rootValid = false
        GS._adoptionEpoch = 0
        GS._peerDatasets = {}
        GS._pendingRelay = {}
        GS._adoption = nil
        initGS()
        GS:EnsureGossipProvider()
        local rec, reason = GS:GetCurrentRecord()
        assertTrue(rec ~= nil, "3C31: staged peer ready name=" .. name
            .. " reason=" .. tostring(reason))
        assertEq(rec.activation, GS.ACTIVATION_STAGED, "3C31: " .. name .. " staged")
        return rec
    end

    local function seedActiveCarol()
        -- Same-dataset staged shell (matching generation/campaign) then cutover.
        seedStagedSameDataset("Carol", "Player-1-Carol", 3)
        assertEq(providerApply(descBody, "Alice-Garona"), "accepted",
            "3C31: carol installs active descriptor")
        local carol = GS:GetCurrentRecord()
        assertEq(carol.activation, GS.ACTIVATION_ACTIVE, "3C31: carol active")
        return carol
    end

    local function bobStagedAdjustment()
        local bob = seedStagedSameDataset("Bob", "Player-1-Bob", 2)
        world.time = cutTs + 60
        local adjOp = select(1, GS:NewAdjustmentOperation(9131, 7, nil))
        assertTrue(adjOp ~= nil, "3C31: bob staged adjustment prepared")
        assertEq(GS:ApplyStagedConfigOperation(adjOp), "accepted",
            "3C31: bob creates staged adjustment after alice cutover")
        bob = GS:GetCurrentRecord()
        local stagedEv = nil
        for i = 1, #(bob.accounting._consumableEvents or {}) do
            local ev = bob.accounting._consumableEvents[i]
            if ev and ev.id == adjOp.id then
                stagedEv = ev
                break
            end
        end
        assertTrue(stagedEv ~= nil, "3C31: bob staged ledger row present")
        assertEq(stagedEv.gsProductionCredit, false, "3C31: staged credit false")
        assertTrue(stagedEv.gsSourceCutoverMarker == nil
            or stagedEv.gsSourceCutoverMarker == "",
            "3C31: staged row has no cutover provenance")
        local adjOpStored = snapshotOp(adjOp)
        local adjEvent = {}
        for k, v in pairs(stagedEv) do adjEvent[k] = v end
        return bob, adjOp, adjOpStored, adjEvent
    end

    local function exportAdjMarker(adjOpId)
        GS:EnsureGossipProvider()
        drainExportMaint(64)
        local bodies = collectAllExportBodies()
        local markerOut, saw = nil, false
        for i = 1, #bodies do
            local body = bodies[i].body
            if body and body.kind == "gs-ledger-event"
                and body.event and (body.event.id == adjOpId or body.event.opId == adjOpId) then
                saw = true
                markerOut = body.cutoverMarker
            end
        end
        assertTrue(saw, "3C31: bob exports ledger body for staged adj")
        return markerOut
    end

    local function carolTotal()
        local progress = GS:ProjectCampaignProgress(campaignId)
        return tonumber(progress and progress.itemTotals and progress.itemTotals[9131]) or 0
    end

    -- Path 1: Bob activates then exports unmarked staged adj → Carol stays at 0.
    local bob, adjOp, adjOpStored, adjEvent = bobStagedAdjustment()
    assertEq(providerApply(descBody, "Alice-Garona"), "accepted",
        "3C31: bob receives activation after staged adj")
    bob = GS:GetCurrentRecord()
    assertEq(bob.activation, GS.ACTIVATION_ACTIVE, "3C31: bob active")
    local bobCredit = nil
    for i = 1, #(bob.accounting._consumableEvents or {}) do
        local ev = bob.accounting._consumableEvents[i]
        if ev and ev.id == adjOp.id then
            bobCredit = ev.gsProductionCredit
            assertTrue(ev.gsSourceCutoverMarker == nil or ev.gsSourceCutoverMarker == "",
                "3C31: activation did not mint provenance on staged adj")
            break
        end
    end
    assertEq(bobCredit, false, "3C31: bob staged adj remains uncredited after activation")
    assertEq(tonumber(GS:ProjectCampaignProgress(campaignId).itemTotals[9131]) or 0, 0,
        "3C31: bob live totals exclude staged adj")
    assertEq(exportAdjMarker(adjOp.id), nil,
        "3C31: bob export must not stamp cutoverMarker on uncredited staged adj")

    local carol = seedActiveCarol()
    local forgedExport = {}
    for k, v in pairs(adjEvent) do forgedExport[k] = v end
    forgedExport.gsProductionCredit = true
    forgedExport.gsSourceCutoverMarker = marker
    local stLedger, reasonLedger = providerApply({
        kind = "gs-ledger-event",
        datasetId = datasetId,
        -- Honest Bob export after fix has nil marker; also reject claimed flags.
        cutoverMarker = nil,
        event = forgedExport,
    }, "Bob-Garona")
    assertTrue(stLedger == "accepted" or stLedger == "duplicate",
        "3C31: carol admits unmarked bob ledger st=" .. tostring(stLedger)
            .. " r=" .. tostring(reasonLedger))
    assertEq(carolTotal(), 0, "3C31: carol does not credit unmarked bob ledger export")

    -- Path 2: unmarked gs-op alone must not mint live credit on active Carol.
    local stOp, reasonOp = providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
    assertTrue(stOp == "accepted" or stOp == "duplicate",
        "3C31: carol admits bob gs-op st=" .. tostring(stOp)
            .. " r=" .. tostring(reasonOp))
    carol = GS:GetCurrentRecord()
    local opCredit = nil
    for i = 1, #(carol.accounting._consumableEvents or {}) do
        local ev = carol.accounting._consumableEvents[i]
        if ev and (ev.id == adjOp.id or ev.opId == adjOp.id) then
            opCredit = ev.gsProductionCredit
            assertTrue(ev.gsSourceCutoverMarker == nil or ev.gsSourceCutoverMarker == "",
                "3C31: remote op did not mint cutover provenance")
            break
        end
    end
    assertEq(opCredit, false, "3C31: remote unmarked op stays uncredited on live carol")
    assertEq(carolTotal(), 0, "3C31: carol totals still zero after unmarked op")

    -- Order variants + reload: still zero; claimed credit flags ignored.
    for _, orderName in ipairs({ "ledger-then-op", "op-then-ledger", "dup-reload" }) do
        carol = seedActiveCarol()
        if orderName == "ledger-then-op" then
            providerApply({
                kind = "gs-ledger-event", datasetId = datasetId, cutoverMarker = nil,
                event = (function()
                    local e = {}
                    for k, v in pairs(adjEvent) do e[k] = v end
                    e.gsProductionCredit = true
                    e.gsSourceCutoverMarker = marker
                    return e
                end)(),
            }, "Bob-Garona")
            providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
        elseif orderName == "op-then-ledger" then
            providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
            providerApply({
                kind = "gs-ledger-event", datasetId = datasetId, cutoverMarker = nil,
                event = adjEvent,
            }, "Bob-Garona")
        else
            providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
            providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
            providerApply({
                kind = "gs-ledger-event", datasetId = datasetId, cutoverMarker = nil,
                event = adjEvent,
            }, "Bob-Garona")
            simulateRuntimeReload()
        end
        assertEq(carolTotal(), 0, "3C31: " .. orderName .. " stays uncredited")
    end

    -- Divergent / arbitrary transport marker must not upgrade the staged body.
    carol = seedActiveCarol()
    providerApply({ kind = "gs-op", op = adjOpStored }, "Bob-Garona")
    providerApply({
        kind = "gs-ledger-event",
        datasetId = datasetId,
        cutoverMarker = "forged-not-canonical",
        event = adjEvent,
    }, "Bob-Garona")
    assertEq(carolTotal(), 0, "3C31: forged transport marker does not mint credit")
    simulateRuntimeReload()
    assertEq(carolTotal(), 0, "3C31: uncredited durable after reload")

    disarmFreshBankSample()
    assertEq(#world.chat, 0, "3C31: no chat")
end



---------------------------------------------------------------------------
-- Codex PR #400 repair batch: A2 / B1 / B2 / C (must run before os.exit)
---------------------------------------------------------------------------

do
    -- A2) Bootstrap fails closed when rank count is unavailable; recovers later.
    -- Exercise InstallStagedDatasetFromRemote and provider ValidateAndApply.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Officer" } -- small guild (2 ranks)
    settleRoster()

    local priorNumRanks = GuildControlGetNumRanks
    GuildControlGetNumRanks = function() return 0 end
    local member = GS.AuthenticateTransportSender("Alice-Garona")
    local okAuth, authReason = GS.SenderHasEditorAuthority(member, { allowBootstrapInstall = true })
    assertEq(okAuth, false, "A2: bootstrap denied while rank count unavailable")
    assertTrue(authReason == "not_ready" or authReason == "rank_unavailable",
        "A2: transient reason got=" .. tostring(authReason))
    local descMissing = {
        kind = "dataset-desc", schemaVersion = 1, guildKey = "club:42",
        datasetId = "a2-missing-ranks", activation = "staged",
        acceptedOpCount = 0, campaignCount = 0, archiveCount = 0,
    }
    local stMiss, reasonMiss = GS:InstallStagedDatasetFromRemote(descMissing, member)
    assertEq(stMiss, "rejected", "A2: install rejected without ranks")
    assertTrue(reasonMiss == "not_ready" or reasonMiss == "rank_unavailable",
        "A2: install reason not permanent unauthorized got=" .. tostring(reasonMiss))
    assertNil(select(1, GS:GetCurrentRecord()), "A2: no dataset installed without ranks")

    -- Provider ValidateAndApply path (dataset-desc) must also fail closed.
    local provider = GG.GetProvider and GG.GetProvider(GS.PROVIDER_ID)
    assertTrue(provider and provider.api and provider.api.ValidateAndApply,
        "A2: provider ValidateAndApply available")
    local vaSt, vaReason = provider.api.ValidateAndApply({
        id = "a2-desc-missing",
        versionFp = "v1",
        body = descMissing,
    }, { sender = "Alice-Garona", peer = "Alice-Garona" })
    assertTrue(vaSt == "rejected" or vaSt == "pending" or vaSt == false or vaSt == nil
            or vaSt == "deferred",
        "A2: provider VA fails closed without ranks st=" .. tostring(vaSt))
    assertNil(select(1, GS:GetCurrentRecord()), "A2: VA did not install without ranks")

    -- Recovery once ranks load: GM bootstrap via the real provider admission path.
    GuildControlGetNumRanks = priorNumRanks
    world.guild.members = {
        { name = "Alice-Garona", guid = "Player-1-Alice", rankOrder = 1, online = true },
        { name = "Bob-Garona", guid = "Player-1-Bob", rankOrder = 2, online = true },
    }
    settleRoster()
    local bob = GS.AuthenticateTransportSender("Bob-Garona")
    local okBob, bobReason = GS.SenderHasEditorAuthority(bob, { allowBootstrapInstall = true })
    assertEq(okBob, true, "A2: last native rank meets the capped officer policy")
    assertEq(bobReason, nil, "A2: capped rank-2 is authorized: " .. tostring(bobReason))
    -- Leave installation to the Guild Master descriptor below so the stored
    -- historical position can be checked without a second dataset.

    local vaGmSt, vaGmReason = provider.api.ValidateAndApply({
        id = "a2-desc-gm",
        versionFp = "v1",
        body = {
            kind = "dataset-desc", schemaVersion = 1, guildKey = "club:42",
            datasetId = "a2-gm", activation = "staged",
            bootstrapEditorRankPosition = 1,
            acceptedOpCount = 0, campaignCount = 0, archiveCount = 0,
        },
    }, { sender = "Alice-Garona", peer = "Alice-Garona" })
    assertTrue(vaGmSt == "accepted" or vaGmSt == true,
        "A2: provider VA accepts GM bootstrap after ranks load st="
            .. tostring(vaGmSt) .. " r=" .. tostring(vaGmReason))
    assertTrue(GS:GetCurrentRecord() ~= nil, "A2: GM bootstrap installed via provider")
    assertEq(GS:GetCurrentRecord().permission.editorRankPosition, 1,
        "A2: advertised historical bootstrap rank is stored as metadata")
    setPlayer("Bob-Garona", "Player-1-Bob", 2)
    assertEq(GS:GetCapabilities().canEdit, true,
        "A2: live edit follows the capped shared officer policy")
    setPlayer("Alice-Garona", "Player-1-Alice", 1)

    -- Ordinary guild (>=3 ranks): authorized editor may bootstrap via provider path.
    resetDb()
    initGS()
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    world.guild.members = {
        { name = "Alice-Garona", guid = "Player-1-Alice", rankOrder = 1, online = true },
        { name = "Bob-Garona", guid = "Player-1-Bob", rankOrder = 2, online = true },
        { name = "Carol-Garona", guid = "Player-1-Carol", rankOrder = 3, online = true },
    }
    settleRoster()
    provider = GG.GetProvider and GG.GetProvider(GS.PROVIDER_ID)
    assertTrue(provider and provider.api and provider.api.ValidateAndApply,
        "A2: provider available for ordinary guild")
    local vaCarolSt, vaCarolReason = provider.api.ValidateAndApply({
        id = "a2-desc-ordinary",
        versionFp = "v1",
        body = {
            kind = "dataset-desc", schemaVersion = 1, guildKey = "club:42",
            datasetId = "a2-ordinary", activation = "staged",
            acceptedOpCount = 0, campaignCount = 0, archiveCount = 0,
        },
    }, { sender = "Carol-Garona", peer = "Carol-Garona" })
    assertTrue(vaCarolSt == "accepted" or vaCarolSt == true,
        "A2: provider VA accepts ordinary-guild rank-3 bootstrap st="
            .. tostring(vaCarolSt) .. " r=" .. tostring(vaCarolReason))
    assertEq(GS:GetCurrentRecord().datasetId, "a2-ordinary",
        "A2: ordinary-guild bootstrap installed via provider")
end

do
    -- B1) Overlapping / mid-flight tab changes require bank reopen; no unsolicited stamp.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    world.guild.ranks = { "Guild Master", "Officer", "Veteran", "Member", "Initiate" }
    settleRoster()
    GS:CreateStagedRecord()
    startCampaign()
    local tabOpA = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 1))
    assertEq(GS:ApplyStagedConfigOperation(tabOpA), "accepted", "B1: set tab A")
    local itemOp = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 100 }, {
        itemId = 100, goal = 1, removed = false,
    }))
    if itemOp then GS:ApplyStagedConfigOperation(itemOp) end

    world.bankTxnCounts = { [1] = 0, [2] = 0 }
    world.bankTabInfo = {
        [1] = { name = "TabA", isViewable = true },
        [2] = { name = "TabB", isViewable = true },
    }
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction()
        return "deposit", "Donor-Garona", nil, 1, nil, nil, 0, 1, 1, 1
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    local queriedTabs = {}
    function QueryGuildBankLog(tab)
        queriedTabs[#queriedTabs + 1] = tab
    end

    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog

    local function resetBankObserver()
        BankLog.bankOpen = true
        BankLog.active = false
        BankLog.awaitingLogUpdate = false
        BankLog.queryRetries = 0
        BankLog.queryToken = 0
        BankLog.activeContext = nil
        BankLog.pendingQuery = nil
        BankLog.pendingAdmit = nil
        BankLog.requireBankReopenForFreshness = false
        BankLog.lastFreshLogAt = nil
        BankLog.lastFreshLogTab = nil
        BankLog.lastFreshLogGuild = nil
    end

    -- Order 1: configure B → OnProfileMaybeChanged (overlap) → late A update.
    resetBankObserver()
    assertEq(BankLog:BeginObservation("open"), true, "B1-o1: begin observation on tab A")
    assertEq(BankLog.pendingQuery and BankLog.pendingQuery.bankTab, 1, "B1-o1: pending bound to A")
    local queriesAfterA = #queriedTabs

    local tabOpB = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 2))
    assertEq(GS:ApplyStagedConfigOperation(tabOpB), "accepted", "B1-o1: switch to tab B")
    BankLog:OnProfileMaybeChanged()
    assertEq(BankLog.requireBankReopenForFreshness, true, "B1-o1: overlap requires bank reopen")
    assertNil(BankLog.pendingQuery, "B1-o1: pending cleared on overlap")
    assertEq(BankLog.awaitingLogUpdate, false, "B1-o1: not awaiting after overlap")
    assertEq(#queriedTabs, queriesAfterA, "B1-o1: no QueryGuildBankLog for B until reopen")

    BankLog:ProcessLogUpdate("late-A-after-profile")
    assertTrue(BankLog.lastFreshLogTab ~= 2,
        "B1-o1: late A must not stamp tab B got=" .. tostring(BankLog.lastFreshLogTab))
    assertEq(GS.IsBankContextSampleReady(2), false, "B1-o1: tab B not ready after late A")
    assertEq(BankLog.requireBankReopenForFreshness, true, "B1-o1: gate remains after late A")
    assertEq(#queriedTabs, queriesAfterA, "B1-o1: late A does not start B query")

    -- Order 2: configure B → late A before OnProfileMaybeChanged (ProcessLogUpdate mismatch).
    local tabOpBackA = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 1))
    assertEq(GS:ApplyStagedConfigOperation(tabOpBackA), "accepted", "B1-o2: restore tab A")
    resetBankObserver()
    BankLog:OnBankClosed()
    BankLog:OnBankOpened()
    assertEq(BankLog.pendingQuery and BankLog.pendingQuery.bankTab, 1, "B1-o2: pending bound to A")
    local queriesBeforeMismatch = #queriedTabs

    local tabOpB2 = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 2))
    assertEq(GS:ApplyStagedConfigOperation(tabOpB2), "accepted", "B1-o2: configure tab B")
    -- Intentionally skip OnProfileMaybeChanged: live EligibleContext is already B.
    BankLog:ProcessLogUpdate("late-A-before-profile")
    assertEq(BankLog.requireBankReopenForFreshness, true,
        "B1-o2: mismatch during completion requires bank reopen")
    assertNil(BankLog.pendingQuery, "B1-o2: pending cleared on mismatch")
    assertEq(BankLog.awaitingLogUpdate, false, "B1-o2: not awaiting after mismatch")
    assertTrue(BankLog.lastFreshLogTab ~= 2,
        "B1-o2: late A must not stamp tab B got=" .. tostring(BankLog.lastFreshLogTab))
    assertEq(GS.IsBankContextSampleReady(2), false, "B1-o2: tab B not ready after mismatch")
    assertEq(#queriedTabs, queriesBeforeMismatch,
        "B1-o2: mismatch must not RequestLog B in the same open session")

    -- OnProfileMaybeChanged after mismatch still must not query B while gated.
    BankLog:OnProfileMaybeChanged()
    assertEq(#queriedTabs, queriesBeforeMismatch,
        "B1-o2: OnProfileMaybeChanged does not query B while reopen required")
    assertEq(GS.IsBankContextSampleReady(2), false, "B1-o2: B still unready after profile notify")

    -- Unsolicited update with no pending query cannot stamp readiness.
    BankLog.requireBankReopenForFreshness = false
    BankLog.pendingQuery = nil
    BankLog.awaitingLogUpdate = false
    BankLog.lastFreshLogTab = nil
    BankLog:ProcessLogUpdate("unsolicited")
    assertNil(BankLog.lastFreshLogTab, "B1: unsolicited update does not stamp")
    assertEq(GS.IsBankContextSampleReady(2), false, "B1: unsolicited leaves B unready")

    -- Clean reopen: verified empty log on B becomes ready.
    BankLog:OnBankClosed()
    assertEq(BankLog.requireBankReopenForFreshness, false, "B1: close clears reopen gate")
    BankLog:OnBankOpened()
    assertEq(BankLog.pendingQuery and BankLog.pendingQuery.bankTab, 2, "B1: reopen queries B")
    assertEq(BankLog.awaitingLogUpdate, true, "B1: awaiting clean B sample")
    BankLog:ProcessLogUpdate("B-ok")
    assertEq(BankLog.lastFreshLogTab, 2, "B1: authentic B sample stamps tab B")
    assertEq(GS.IsBankContextSampleReady(2), true, "B1: tab B ready after clean sample")

    -- Verified empty log already covered (txn count 0). Guild switch cancels stamp.
    world.guild.clubId = 99
    settleRoster()
    fireEvent("GUILD_ROSTER_UPDATE")
    BankLog:OnProfileMaybeChanged()
    assertEq(GS.IsBankContextSampleReady(2), false,
        "B1: guild switch leaves prior tab readiness unavailable")

    GetGuildBankTabInfo = nil
    QueryGuildBankLog = nil
    world.guild.clubId = 42
    settleRoster()
end

do
    -- B2) Deferred admit recovers via After(0) after the same roster event settles.
    -- Never call TryAdmitPendingSnapshot as a test fallback.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    local record = seedActivatableCampaign(9402, 5)
    local itemOp = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 100 }, {
        itemId = 100, goal = 5, removed = false,
    }))
    if itemOp then assertEq(GS:ApplyStagedConfigOperation(itemOp), "accepted", "B2: seed item 100") end
    local _, stAct = GS:ActivateCanonicalDataset()
    assertEq(stAct, "accepted", "B2: activate for live observation")

    world.bankTxnCounts = { [2] = 1 }
    world.bankTabInfo = { [2] = { name = "Supplies", isViewable = true } }
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction()
        return "deposit", "Alice-Garona", "|cffffffff|Hitem:100::::::::|h[Item]|h|r",
            1, nil, nil, 0, 0, 0, 0
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    function QueryGuildBankLog() end

    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    BankLog.bankOpen = true
    BankLog.active = false
    BankLog.awaitingLogUpdate = false
    BankLog.pendingAdmit = nil
    BankLog.rosterAdmitFrame = nil
    BankLog.rosterAdmitGen = 0
    BankLog.requireBankReopenForFreshness = false
    BankLog.lastFreshLogTab = nil

    local priorGetCtx = GS.GetCurrentContext
    local ctxBlocked = true
    function GS:GetCurrentContext()
        if ctxBlocked then
            return {
                ready = false,
                reason = "roster_incomplete",
                guildKey = "club:42",
                handleGeneration = 1,
            }
        end
        return priorGetCtx(self)
    end

    local function frameOnEvent(frame)
        return frame and (frame._onEvent or (frame.scripts and frame.scripts.OnEvent))
    end

    local function assertOneWitness(label)
        local stats = BankLog.lastStats or {}
        assertEq(stats.pending or 0, 1,
            label .. ": exactly one qualifying witness pending="
                .. tostring(stats.pending) .. " admitted=" .. tostring(stats.admitted))
        assertEq(stats.admitted or 0, 0, label .. ": single witness does not auto-credit")
        local pendingRows = GS:ListPendingEvidence(GS:GetCurrentRecord().currentCampaignId, 64)
        assertTrue(type(pendingRows) == "table" and #pendingRows == 1,
            label .. ": exactly one pending evidence cluster")
        assertEq(pendingRows[1].witnessCount or 0, 1,
            label .. ": exactly one independent witness in cluster")
        assertEq(pendingRows[1].itemId, 100, label .. ": recovered witness is item 100")
        return pendingRows
    end

    -- Scenario 1: bank listener runs first; authority settles before After(0); one event.
    assertEq(BankLog:BeginObservation("open"), true, "B2-s1: begin live observation")
    BankLog:ProcessLogUpdate("early")
    assertTrue(type(BankLog.pendingAdmit) == "table", "B2-s1: snapshot retained while roster incomplete")
    assertTrue(BankLog.lastStats and BankLog.lastStats.deferred == true, "B2-s1: admit deferred")
    assertTrue(BankLog.rosterAdmitFrame ~= nil, "B2-s1: roster admit listener armed")
    local frame = BankLog.rosterAdmitFrame
    local onEvent = frameOnEvent(frame)
    assertTrue(type(onEvent) == "function", "B2-s1: roster listener has OnEvent")

    timers = {}
    onEvent(frame, "GUILD_ROSTER_UPDATE")
    assertTrue(#timers >= 1, "B2-s1: After(0) scheduled from roster event")
    assertTrue(type(BankLog.pendingAdmit) == "table",
        "B2-s1: still pending immediately (before deferred evaluate)")
    -- Same event: roster authority settles before the deferred callback runs.
    ctxBlocked = false
    world.time = (world.time or 0) + 0.01
    flushTimers()
    assertNil(BankLog.pendingAdmit, "B2-s1: pending admit cleared by deferred callback")
    assertTrue(BankLog.rosterAdmitFrame == nil, "B2-s1: roster listener released after admit")
    local pendingRows = assertOneWitness("B2-s1")

    -- Duplicate roster event on a released listener must not double-admit.
    onEvent(frame, "GUILD_ROSTER_UPDATE")
    world.time = (world.time or 0) + 0.01
    flushTimers()
    local pendingAfterDup = GS:ListPendingEvidence(GS:GetCurrentRecord().currentCampaignId, 64)
    assertEq(pendingAfterDup[1].witnessCount or 0, 1,
        "B2-s1: no duplicate witness after second roster event")
    assertEq(#pendingAfterDup, #pendingRows, "B2-s1: no extra pending clusters")

    -- Scenario 2: authority already settled before the bank listener runs; one event.
    do
        local rec = GS:GetCurrentRecord()
        if rec and rec.observations and rec.observations.byCampaign then
            rec.observations.byCampaign[rec.currentCampaignId] = nil
        end
    end
    BankLog.pendingAdmit = nil
    BankLog.rosterAdmitFrame = nil
    BankLog.rosterAdmitGen = 0
    BankLog.lastStats = nil
    BankLog.bankOpen = true
    BankLog.active = true
    BankLog.requireBankReopenForFreshness = false
    ctxBlocked = false
    BankLog:RequestLog("s2-rearm")
    assertEq(BankLog.awaitingLogUpdate, true, "B2-s2: rearmed bank query")
    ctxBlocked = true
    BankLog:ProcessLogUpdate("s2-early")
    assertTrue(type(BankLog.pendingAdmit) == "table", "B2-s2: snapshot retained")
    assertTrue(BankLog.lastStats and BankLog.lastStats.deferred == true, "B2-s2: admit deferred")
    frame = BankLog.rosterAdmitFrame
    onEvent = frameOnEvent(frame)
    assertTrue(type(onEvent) == "function", "B2-s2: listener armed")
    -- Authority already ready before the listener observes the roster event.
    ctxBlocked = false
    timers = {}
    onEvent(frame, "GUILD_ROSTER_UPDATE")
    assertTrue(#timers >= 1, "B2-s2: After(0) scheduled")
    world.time = (world.time or 0) + 0.01
    flushTimers()
    assertNil(BankLog.pendingAdmit, "B2-s2: pending cleared after one settled event")
    assertTrue(BankLog.rosterAdmitFrame == nil, "B2-s2: listener released")
    assertOneWitness("B2-s2")

    -- Guild change while deferred: drop snapshot (no stale admission).
    BankLog.pendingAdmit = {
        ctx = BankLog.activeContext or { bankTab = 2, guildGuid = "club:42" },
        snapshot = { rows = {} },
    }
    BankLog:EnsureRosterAdmitListener()
    local guildFrame = BankLog.rosterAdmitFrame
    local guildOnEvent = frameOnEvent(guildFrame)
    assertTrue(type(guildOnEvent) == "function", "B2: guild-change listener armed")
    guildOnEvent(guildFrame, "PLAYER_GUILD_UPDATE")
    assertNil(BankLog.pendingAdmit, "B2: guild change clears pending admit")
    assertTrue(BankLog.rosterAdmitFrame == nil, "B2: guild change releases listener")

    -- Tab change while deferred: live mismatch discarded by deferred evaluate.
    BankLog.bankOpen = true
    BankLog.active = true
    BankLog.pendingAdmit = {
        ctx = {
            bankTab = 2, guildGuid = "club:42", profileId = "p",
            datasetId = GS:GetCurrentRecord().datasetId,
            campaignId = GS:GetCurrentRecord().currentCampaignId,
            generation = 1,
        },
        snapshot = { rows = { { kind = "deposit" } } },
    }
    BankLog:EnsureRosterAdmitListener()
    local tabFrame = BankLog.rosterAdmitFrame
    local tabOnEvent = frameOnEvent(tabFrame)
    assertTrue(type(tabOnEvent) == "function", "B2: tab-change listener armed")
    local priorEligible = BankLog.EligibleContext
    function BankLog:EligibleContext()
        return {
            source = "guildSupplies", bankTab = 3, guildGuid = "club:42",
            profileId = "p", datasetId = GS:GetCurrentRecord().datasetId,
            campaignId = GS:GetCurrentRecord().currentCampaignId, generation = 1,
        }
    end
    timers = {}
    tabOnEvent(tabFrame, "GUILD_ROSTER_UPDATE")
    world.time = (world.time or 0) + 0.01
    flushTimers()
    assertNil(BankLog.pendingAdmit, "B2: tab change clears pending admit via deferred evaluate")
    assertTrue(BankLog.rosterAdmitFrame == nil, "B2: tab change releases listener")
    BankLog.EligibleContext = priorEligible

    -- Bank close clears deferred state / listeners.
    BankLog.pendingAdmit = { ctx = {}, snapshot = { rows = {} } }
    BankLog:EnsureRosterAdmitListener()
    BankLog:OnBankClosed()
    assertNil(BankLog.pendingAdmit, "B2: bank close clears pending admit")
    assertTrue(BankLog.rosterAdmitFrame == nil, "B2: bank close releases listener")

    GS.GetCurrentContext = priorGetCtx
    GetGuildBankTabInfo = nil
    QueryGuildBankLog = nil
    disarmFreshBankSample()
end

do
    -- C) Export GetRecordBody must not rescan the native roster per record.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    startCampaign()
    for i = 1, 12 do
        local op = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 1000 + i }, {
            itemId = 1000 + i, goal = i, removed = false,
        }))
        assertEq(GS:ApplyStagedConfigOperation(op), "accepted", "C: seed item " .. i)
    end
    if GS.NotifyLocalDurableChange then
        GS.NotifyLocalDurableChange("test-c-export")
    end
    local provider = GG.GetProvider and GG.GetProvider(GS.PROVIDER_ID)
    assertTrue(provider and provider.api and provider.api.GetRecordBody,
        "C: provider GetRecordBody available")
    local ids = {}
    if provider.api.ListRecordIds then
        local page = select(1, provider.api.ListRecordIds(1, 64))
        for i = 1, #(page or {}) do
            ids[#ids + 1] = page[i]
        end
    end
    assertTrue(#ids >= 8, "C: export has multiple record ids got=" .. tostring(#ids))

    local walks = 0
    local priorGetRoster = GetGuildRosterInfo
    GetGuildRosterInfo = function(i)
        walks = walks + 1
        return priorGetRoster(i)
    end
    assertTrue(GS:GetCurrentContext().ready == true, "C: context ready before export hot path")
    local baselineWalks = walks
    walks = 0
    for i = 1, math.min(8, #ids) do
        local body = provider.api.GetRecordBody(ids[i])
        assertTrue(type(body) == "table", "C: body " .. tostring(ids[i]))
        if provider.api.GetRecordVersionFp then
            assertTrue(type(provider.api.GetRecordVersionFp(ids[i])) == "string",
                "C: versionFp " .. tostring(ids[i]))
        end
    end
    assertTrue(walks <= 2,
        "C: roster walks must not scale with GetRecordBody count walks="
            .. tostring(walks) .. " baselineWarm=" .. tostring(baselineWalks))

    world.guild.clubId = 88
    settleRoster()
    fireEvent("GUILD_ROSTER_UPDATE")
    local staleBody = provider.api.GetRecordBody(ids[1])
    assertNil(staleBody, "C: stale export body withheld after guild switch")
    GetGuildRosterInfo = priorGetRoster
    world.guild.clubId = 42
    settleRoster()
    fireEvent("GUILD_ROSTER_UPDATE")
end

