do
    -- A1) Remote InstallRemoteLiveCutover preserves later item cutoffs (refreshOnly).
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    local record = seedActivatableCampaign(9201, 5)
    local cfg = record.accounting._consumables
    local cutoverAt = 5000000
    local laterItemCutoff = cutoverAt + 3600
    cfg.eligibility = {
        items = { ["9201"] = laterItemCutoff },
        tabEligibleFrom = cutoverAt - 100,
        baselineEstablished = true,
        baselineAt = cutoverAt - 100,
    }
    local cutover = {
        schemaVersion = 1,
        datasetId = record.datasetId,
        guildKey = "club:42",
        activatedAt = cutoverAt,
        activatedByGuid = "Player-1-Alice",
        activatedByName = "Alice-Garona",
        bankTab = 2,
        contextStatus = "empty",
        contextObservedAt = cutoverAt,
        contextRecordCount = 0,
        eligibilityBoundary = {
            baselineEstablished = true,
            tabEligibleFrom = cutoverAt,
        },
    }
    cutover.cutoverMarker = GS.BuildCutoverMarker(cutover.datasetId, cutover.activatedAt, cutover.bankTab)
    local st, reason = GS.InstallRemoteLiveCutover(record, cutover, "club:42", {
        quarantinePending = true,
    })
    assertEq(st, "accepted", "A1: remote cutover accepted r=" .. tostring(reason))
    assertEq(record.activation, GS.ACTIVATION_ACTIVE, "A1: record active")
    assertEq(cfg.eligibility.items["9201"], laterItemCutoff,
        "A1: later item re-add cutoff preserved through remote cutover")
    assertTrue((tonumber(cfg.eligibility.tabEligibleFrom) or 0) >= cutoverAt,
        "A1: tab floor raised to cutover")
    assertEq(cfg.eligibility.baselineEstablished, true, "A1: baseline remains established")

    -- Local activation still fully replaces eligibility (intentional).
    resetDb()
    initGS()
    record = seedActivatableCampaign(9202, 5)
    cfg = record.accounting._consumables
    cfg.eligibility.items = cfg.eligibility.items or {}
    cfg.eligibility.items["9202"] = 9999999
    armFreshBankSample(true)
    local _, stAct = GS:ActivateCanonicalDataset()
    assertEq(stAct, "accepted", "A1: local activation accepted")
    cfg = GS:GetCurrentRecord().accounting._consumables
    local nItems = 0
    for _ in pairs(cfg.eligibility.items or {}) do nItems = nItems + 1 end
    assertEq(nItems, 0, "A1: local activation replaces eligibility.items")
    disarmFreshBankSample()
end

do
    -- A1b) Item cutoff earlier than cutover is floored, never left below boundary.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    local record = seedActivatableCampaign(9203, 5)
    local cfg = record.accounting._consumables
    local cutoverAt = 6000000
    cfg.eligibility = {
        items = { ["9203"] = cutoverAt - 500 },
        tabEligibleFrom = cutoverAt - 500,
        baselineEstablished = true,
        baselineAt = cutoverAt - 500,
    }
    local cutover = {
        schemaVersion = 1,
        datasetId = record.datasetId,
        guildKey = "club:42",
        activatedAt = cutoverAt,
        activatedByGuid = "Player-1-Alice",
        activatedByName = "Alice-Garona",
        bankTab = 2,
        contextStatus = "empty",
        contextObservedAt = cutoverAt,
        contextRecordCount = 0,
        eligibilityBoundary = {
            baselineEstablished = true,
            tabEligibleFrom = cutoverAt,
        },
    }
    cutover.cutoverMarker = GS.BuildCutoverMarker(cutover.datasetId, cutover.activatedAt, cutover.bankTab)
    assertEq(GS.InstallRemoteLiveCutover(record, cutover, "club:42"), "accepted",
        "A1b: remote cutover accepted")
    assertEq(cfg.eligibility.items["9203"], cutoverAt,
        "A1b: pre-cutover item cutoff floored to boundary")
end

do
    -- A2) Legacy observation isolation + different-tab GS sample acquisition.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS._BankContextReadinessProbe = nil
    GS:CreateStagedRecord()
    startCampaign()
    local tabOp = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 2))
    assertEq(GS:ApplyStagedConfigOperation(tabOp), "accepted", "A2: GS bank tab 2")
    -- GS requests item 100 only; legacy will request a different item at a higher generation.
    local itemOp = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 100 }, {
        itemId = 100, goal = 5, removed = false,
    }))
    assertEq(GS:ApplyStagedConfigOperation(itemOp), "accepted", "A2: GS item 100")

    loadModule("SpectrumFederation/modules/LootHelper/Consumables.lua")
    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesVerification.lua")
    local C = SF.Consumables
    assertTrue(C and C.Ensure, "A2: Consumables API present")
    local selfId = SF.NameUtil.GetSelfId()
    assertTrue(type(selfId) == "string" and selfId ~= "", "A2: self id available")
    local profile = {
        _profileId = "profile-a2-legacy",
        _adminUsers = { selfId },
        _consumables = {
            guild = { guid = "42", name = "Spectrum", realm = "Garona" },
            bankTab = 2,
            requestedItems = { ["200"] = { itemId = 200, goal = 5 } },
            generation = 5,
            configSeq = 0,
            itemSeq = 0,
            eligibility = { items = {}, tabEligibleFrom = nil, baselineEstablished = false },
            txnRegistry = {},
        },
        _consumableEvents = {},
        _consumableEventArchive = {},
    }
    function profile:GetProfileId() return self._profileId end
    function profile:IsAdminMemberId(memberId) return memberId == selfId end
    local priorGetActive = SF.GetActiveProfile
    local priorRuntime = SF.ConsumablesRuntime
    SF.GetActiveProfile = function() return profile end
    SF.ConsumablesRuntime = {
        AccountingProfile = function() return profile end,
        CurrentGuild = function()
            return { guid = "42", name = "Spectrum", realm = "Garona" }
        end,
    }
    SF.lootHelperDB = { profiles = { [profile._profileId] = profile } }
    assertEq(C.LegacyWritersAllowed(profile), true, "A2: legacy writers allowed while staged")

    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    local ctx = BankLog:EligibleContext()
    assertTrue(ctx ~= nil and ctx.sampleOnly == true, "A2: sample-only context selected")
    assertTrue(type(ctx.legacy) == "table" and ctx.legacy.source == "legacyProfile",
        "A2: same-tab legacy companion attached")
    assertEq(ctx.legacy.generation, 5, "A2: companion carries legacy generation")
    assertTrue(ctx.legacy.requestedSet[200] or ctx.legacy.requestedSet["200"],
        "A2: companion requests legacy item 200")

    -- Filler (non-requested) + legacy-only deposit so the eligible row has neighbors.
    world.bankTxnRows = {
        [2] = {
            { "deposit", "Alice-Garona", "|cffffffff|Hitem:50::::::::|h[Filler]|h|r", 1, nil, nil, 0, 0, 0, 0 },
            { "deposit", "Alice-Garona", "|cffffffff|Hitem:200::::::::|h[Legacy]|h|r", 3, nil, nil, 0, 0, 0, 0 },
        },
    }
    world.bankTxnCounts = { [2] = 2, [3] = 0 }
    world.bankTabInfo = {
        [2] = { name = "Supplies", isViewable = true },
        [3] = { name = "Other", isViewable = true },
    }
    world.currentGuildBankTab = 2
    function GetCurrentGuildBankTab() return world.currentGuildBankTab end
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction(tab, index)
        local rows = world.bankTxnRows[tab]
        local row = rows and rows[index]
        if not row then return nil end
        return unpack(row)
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    function QueryGuildBankLog() end

    BankLog.bankOpen = true
    BankLog.active = false
    BankLog.requireBankReopenForFreshness = false
    BankLog.pendingQuery = nil
    BankLog.awaitingLogUpdate = false
    BankLog.lastLegacyStats = nil
    assertEq(BankLog:BeginObservation("open"), true, "A2: begin observation")
    BankLog:ProcessLogUpdate("a2-disjoint-items")
    assertEq(BankLog.lastFreshLogTab, 2, "A2: GS sample stamped")
    assertEq(GS.IsBankContextSampleReady(2), true, "A2: GS sample ready")
    assertTrue(BankLog.lastStats and BankLog.lastStats.sampleOnly == true,
        "A2: no staged GS donation admission")
    assertTrue(type(BankLog.lastLegacyStats) == "table"
        and (BankLog.lastLegacyStats.created or 0) >= 1,
        "A2: legacy created observation for disjoint item")
    local store = SF.ConsumablesObservation.EnsureProfileStore(SF.lootHelperDB, profile._profileId)
    local scope = store and SF.ConsumablesObservation.EnsureScope(store, "42", 2)
    local foundLegacyObs = false
    for i = 1, #(scope and scope.observations or {}) do
        local obs = scope.observations[i]
        if type(obs) == "table" and tonumber(obs.itemId) == 200
            and tonumber(obs.generation) == 5 then
            foundLegacyObs = true
            break
        end
    end
    assertTrue(foundLegacyObs, "A2: legacy observation uses item 200 generation 5")
    assertTrue(profile._consumables.eligibility.baselineEstablished == true,
        "A2: legacy baseline established")
    assertTrue(type(BankLog.lastVerifyStats) == "table"
        and (BankLog.lastVerifyStats.trusted or 0) >= 1,
        "A2: legacy admin trust credited donation")
    assertTrue(#(profile._consumableEvents or {}) >= 1,
        "A2: legacy ledger received credited event")
    -- GS must not have admitted the legacy-only deposit into staged accounting.
    local gsRec = GS:GetCurrentRecord()
    assertEq(#(gsRec.accounting._consumableEvents or {}), 0,
        "A2: staged GS ledger empty")

    -- Mid-query: disable legacy eligibility so live.legacy is nil. Must not fall
    -- back to a pending companion and write the prior profile.
    BankLog.pendingQuery = nil
    BankLog.awaitingLogUpdate = false
    BankLog.requireBankReopenForFreshness = false
    BankLog.active = false
    BankLog.lastLegacyStats = nil
    local priorObsCount = #(scope and scope.observations or {})
    assertEq(BankLog:BeginObservation("open"), true, "A2: begin before legacy disable")
    assertTrue(type(BankLog.pendingQuery) == "table", "A2: query outstanding before disable")
    local savedItems = profile._consumables.requestedItems
    profile._consumables.requestedItems = {}
    BankLog:ProcessLogUpdate("a2-stale-legacy-disabled")
    assertTrue(BankLog.lastLegacyStats == nil,
        "A2: disabled legacy mid-query skips companion reconcile")
    local afterDisableCount = #(scope and scope.observations or {})
    assertEq(afterDisableCount, priorObsCount,
        "A2: disabled legacy mid-query does not append stale observations")
    profile._consumables.requestedItems = savedItems

    -- Different tabs via production Guild Bank events (no manual observer clears).
    -- Legacy Tab 2 remains authoritative; GS Tab 3 is sampled by selecting that tab
    -- (Retail: GuildBankTab_OnClick → QueryGuildBankTab → GUILDBANKBAGSLOTS_CHANGED).
    local tabOp3 = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 3))
    assertEq(GS:ApplyStagedConfigOperation(tabOp3), "accepted", "A2: GS tab 3")
    profile._consumables.bankTab = 2
    world.bankTxnCounts[3] = 0
    world.bankTxnRows[3] = {}
    world.logQueries = {}
    function QueryGuildBankLog(tab)
        world.logQueries[#world.logQueries + 1] = tab
    end
    GS._BankContextReadinessProbe = nil

    -- Fresh bank open on legacy Tab 2 through the production open event.
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")
    world.currentGuildBankTab = 2
    BankLog:OnEvent("GUILDBANKFRAME_OPENED")
    assertTrue(BankLog.active, "A2: observer active after open on legacy tab")
    assertEq(BankLog.activeContext and BankLog.activeContext.source, "legacyProfile",
        "A2: open on tab 2 prefers legacy")
    assertEq(BankLog.activeContext.bankTab, 2, "A2: observing legacy tab 2")
    assertTrue(#world.logQueries >= 1 and world.logQueries[#world.logQueries] == 2,
        "A2: open queries legacy tab 2")
    local legacyObsBefore = #(scope and scope.observations or {})
    BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    assertEq(BankLog.lastFreshLogTab, 2, "A2: legacy-tab query stamps tab 2")
    assertEq(BankLog.awaitingLogUpdate, false, "A2: legacy query completed")
    local gsReady, gsReadyReason = GS.IsBankContextSampleReady(3)
    assertEq(gsReady, false,
        "A2: legacy-tab never stamps GS tab 3 reason=" .. tostring(gsReadyReason))
    assertTrue(#(scope and scope.observations or {}) >= legacyObsBefore,
        "A2: legacy observation remains operational on tab 2")

    -- Outstanding Tab 2 response must not satisfy Tab 3: start a new Tab 2 cycle,
    -- then select Tab 3 while that query is still awaiting → reopen gate.
    world.time = (world.time or 0) + 2
    local queriesBeforeOverlap = #world.logQueries
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertTrue(BankLog.awaitingLogUpdate, "A2: same-tab slots_changed re-arms tab 2 query")
    assertEq(world.logQueries[#world.logQueries], 2, "A2: slots_changed still queries tab 2")
    world.currentGuildBankTab = 3
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertEq(BankLog.requireBankReopenForFreshness, true,
        "A2: selecting GS tab during outstanding tab-2 query requires reopen")
    assertTrue(BankLog.awaitingLogUpdate == false,
        "A2: overlap clears awaiting until reopen")
    local queriesAfterOverlap = #world.logQueries
    assertEq(queriesAfterOverlap, queriesBeforeOverlap + 1,
        "A2: overlap does not issue an uncorrelated tab-3 query")
    -- Late GUILDBANKLOG_UPDATE for the abandoned Tab 2 query must not stamp Tab 3.
    BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    assertTrue(BankLog.lastFreshLogTab ~= 3,
        "A2: late tab-2 response does not stamp GS tab 3")
    assertEq(GS.IsBankContextSampleReady(3), false,
        "A2: Tab 3 readiness unavailable until clean reopen sample")

    local guide = GS.FormatActivationGuidance({
        reason = "tab_not_ready",
        configuredBankTab = 3,
    })
    assertTrue(type(guide) == "string" and guide:find("tab 3", 1, true),
        "A2: Settings guide names GS tab for split-tab sample")
    assertTrue(guide:find("tab 2", 1, true),
        "A2: Settings guide names legacy tab for split-tab sample")
    assertTrue(guide:find("close and reopen", 1, true) or guide:find("reopen", 1, true),
        "A2: Settings guide explains reopen when a query was interrupted")

    -- Documented mandatory reopen with GS Tab 3 selected.
    world.currentGuildBankTab = 3
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")
    assertEq(BankLog.requireBankReopenForFreshness, false,
        "A2: bank close clears freshness reopen gate")
    assertEq(BankLog.active, false, "A2: observer idle after close")
    BankLog:OnEvent("GUILDBANKFRAME_OPENED")
    assertTrue(BankLog.active, "A2: observer active after reopen on GS tab")
    local gsSampleCtx = BankLog.activeContext
    assertTrue(gsSampleCtx and gsSampleCtx.sampleOnly == true and gsSampleCtx.bankTab == 3,
        "A2: reopen on GS tab selects sample-only")
    assertNil(gsSampleCtx.legacy, "A2: different-tab sample has no legacy companion")
    assertEq(world.logQueries[#world.logQueries], 3,
        "A2: reopen issues authentic Tab 3 QueryGuildBankLog")
    assertEq(BankLog.pendingQuery and BankLog.pendingQuery.bankTab, 3,
        "A2: pending query bound to Tab 3")
    BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    assertEq(BankLog.lastFreshLogTab, 3, "A2: GS tab sample stamped via production log update")
    assertEq(GS.IsBankContextSampleReady(3), true, "A2: GS activation sample ready on tab 3")
    assertTrue(BankLog.lastStats and BankLog.lastStats.sampleOnly == true,
        "A2: empty GS sample admits nothing")
    assertEq(C.LegacyWritersAllowed(profile), true,
        "A2: legacy writers still allowed until activation")

    -- Completed Tab 3 sample → ActivateCanonicalDataset without readiness probe.
    GS._BankContextReadinessProbe = nil
    local _, stAct, actReason = GS:ActivateCanonicalDataset()
    assertEq(stAct, "accepted",
        "A2: activate after real GS sample reason=" .. tostring(actReason))
    local liveCtx = BankLog:EligibleContext()
    assertTrue(liveCtx and liveCtx.source == "guildSupplies" and not liveCtx.sampleOnly,
        "A2: post-activation live GS context")
    assertNil(liveCtx.legacy, "A2: no legacy companion after activation")
    assertEq(C.LegacyWritersAllowed(profile), false, "A2: legacy writers disabled")

    -- After activation, selecting the old legacy tab must not resume legacy observation.
    world.currentGuildBankTab = 2
    world.time = (world.time or 0) + 2
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertTrue(BankLog.activeContext and BankLog.activeContext.source == "guildSupplies"
        and not BankLog.activeContext.sampleOnly,
        "A2: post-activation slots_changed stays on live GS")
    assertEq(BankLog.activeContext.bankTab, 3,
        "A2: live GS still targets configured tab 3 after selecting legacy tab")
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")

    SF.GetActiveProfile = priorGetActive
    SF.ConsumablesRuntime = priorRuntime
    GetGuildBankTabInfo = nil
    GetGuildBankTransaction = nil
    GetNumGuildBankTransactions = nil
    GetCurrentGuildBankTab = nil
    QueryGuildBankLog = nil
end

do
    -- A2-event) Completed legacy Tab 2 query then select GS Tab 3 via
    -- GUILDBANKBAGSLOTS_CHANGED (no reopen needed when no outstanding query).
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS._BankContextReadinessProbe = nil
    GS:CreateStagedRecord()
    startCampaign()
    local tabOp = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 3))
    assertEq(GS:ApplyStagedConfigOperation(tabOp), "accepted", "A2-event: GS bank tab 3")
    local itemOp = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 100 }, {
        itemId = 100, goal = 5, removed = false,
    }))
    assertEq(GS:ApplyStagedConfigOperation(itemOp), "accepted", "A2-event: GS item 100")

    loadModule("SpectrumFederation/modules/LootHelper/Consumables.lua")
    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesVerification.lua")
    local C = SF.Consumables
    local selfId = SF.NameUtil.GetSelfId()
    local profile = {
        _profileId = "profile-a2-event",
        _adminUsers = { selfId },
        _consumables = {
            guild = { guid = "42", name = "Spectrum", realm = "Garona" },
            bankTab = 2,
            requestedItems = { ["200"] = { itemId = 200, goal = 5 } },
            generation = 5,
            configSeq = 0,
            itemSeq = 0,
            eligibility = { items = {}, tabEligibleFrom = nil, baselineEstablished = false },
            txnRegistry = {},
        },
        _consumableEvents = {},
        _consumableEventArchive = {},
    }
    function profile:GetProfileId() return self._profileId end
    function profile:IsAdminMemberId(memberId) return memberId == selfId end
    local priorGetActive = SF.GetActiveProfile
    local priorRuntime = SF.ConsumablesRuntime
    SF.GetActiveProfile = function() return profile end
    SF.ConsumablesRuntime = {
        AccountingProfile = function() return profile end,
        CurrentGuild = function()
            return { guid = "42", name = "Spectrum", realm = "Garona" }
        end,
    }
    SF.lootHelperDB = { profiles = { [profile._profileId] = profile } }

    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    -- Isolate from prior A2 bank-open / activation residue via production close.
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")
    world.bankTxnRows = {
        [2] = {
            { "deposit", "Alice-Garona", "|cffffffff|Hitem:200::::::::|h[Legacy]|h|r", 2, nil, nil, 0, 0, 0, 0 },
        },
        [3] = {},
    }
    world.bankTxnCounts = { [2] = 1, [3] = 0 }
    world.bankTabInfo = {
        [2] = { name = "Legacy", isViewable = true },
        [3] = { name = "Supplies", isViewable = true },
    }
    world.currentGuildBankTab = 2
    world.logQueries = {}
    function GetCurrentGuildBankTab() return world.currentGuildBankTab end
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction(tab, index)
        local rows = world.bankTxnRows[tab]
        local row = rows and rows[index]
        if not row then return nil end
        return unpack(row)
    end
    function GetGuildBankTabInfo(tab)
        local info = world.bankTabInfo[tab]
        if not info then return nil end
        return info.name, nil, info.isViewable
    end
    function QueryGuildBankLog(tab)
        world.logQueries[#world.logQueries + 1] = tab
    end

    BankLog:OnEvent("GUILDBANKFRAME_OPENED")
    assertEq(BankLog.activeContext and BankLog.activeContext.bankTab, 2,
        "A2-event: open observes legacy tab 2")
    assertEq(BankLog.requireBankReopenForFreshness, false,
        "A2-event: clean open has no reopen gate")
    BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    assertEq(BankLog.awaitingLogUpdate, false, "A2-event: tab 2 query completed")
    assertEq(BankLog.lastFreshLogTab, 2, "A2-event: tab 2 stamped")
    assertEq(C.LegacyWritersAllowed(profile), true, "A2-event: legacy writers before sample")

    -- Select GS Tab 3 after the Tab 2 cycle completed: no reopen required.
    world.currentGuildBankTab = 3
    world.time = (world.time or 0) + 2
    local qBefore = #world.logQueries
    BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
    assertEq(BankLog.requireBankReopenForFreshness, false,
        "A2-event: completed prior query allows in-session retarget")
    assertTrue(BankLog.activeContext and BankLog.activeContext.sampleOnly
        and BankLog.activeContext.bankTab == 3,
        "A2-event: slots_changed retargets to GS sample tab 3")
    assertEq(#world.logQueries, qBefore + 1, "A2-event: one new query after tab select")
    assertEq(world.logQueries[#world.logQueries], 3,
        "A2-event: QueryGuildBankLog(3) after selecting GS tab")
    BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    assertEq(BankLog.lastFreshLogTab, 3, "A2-event: Tab 3 sample stamped")
    assertEq(GS.IsBankContextSampleReady(3), true, "A2-event: Tab 3 readiness from real sample")
    GS._BankContextReadinessProbe = nil
    local _, stAct = GS:ActivateCanonicalDataset()
    assertEq(stAct, "accepted", "A2-event: activate from slots_changed sample")
    assertEq(C.LegacyWritersAllowed(profile), false, "A2-event: legacy writers stop after activation")

    -- Repeated tab selections / close-reopen stay bounded (no loops).
    local qMark = #world.logQueries
    for _ = 1, 5 do
        world.currentGuildBankTab = 2
        world.time = (world.time or 0) + 2
        BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
        world.currentGuildBankTab = 3
        world.time = (world.time or 0) + 2
        BankLog:OnEvent("GUILDBANKBAGSLOTS_CHANGED")
        if BankLog.awaitingLogUpdate then
            BankLog:OnEvent("GUILDBANKLOG_UPDATE")
        end
    end
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")
    world.currentGuildBankTab = 3
    BankLog:OnEvent("GUILDBANKFRAME_OPENED")
    if BankLog.awaitingLogUpdate then
        BankLog:OnEvent("GUILDBANKLOG_UPDATE")
    end
    assertTrue(#world.logQueries < qMark + 40,
        "A2-event: repeated selections stay bounded queries=" .. tostring(#world.logQueries - qMark))
    assertTrue(BankLog.activeContext and BankLog.activeContext.source == "guildSupplies",
        "A2-event: still live GS after churn")
    BankLog:OnEvent("GUILDBANKFRAME_CLOSED")

    SF.GetActiveProfile = priorGetActive
    SF.ConsumablesRuntime = priorRuntime
    GetGuildBankTabInfo = nil
    GetGuildBankTransaction = nil
    GetNumGuildBankTransactions = nil
    GetCurrentGuildBankTab = nil
    QueryGuildBankLog = nil
end

do
    -- B3) Ops-store validation fast path: measure + immutability + invalidation.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    startCampaign()
    local record = GS:GetCurrentRecord()
    local datasetId = record.datasetId
    local raw = SpectrumFederationDB.guildSupplies.guilds["club:42"]
    local function seedAccepted(n)
        local ops = raw.operations
        for i = 1, n do
            local id = "perf-" .. i
            ops.records[id] = minimalValidBankTabBody(id, datasetId, (i % 8) + 1)
            ops.order[#ops.order + 1] = id
        end
        ops.heads = {}
        if GS._BumpOpsValidationGen then
            GS._BumpOpsValidationGen(ops)
        end
    end
    local function measureReads(label, reps)
        GS._opsValidationFullScans = 0
        GS._opsValidationBodyScans = 0
        GS._opsValidationOrderIters = 0
        -- Prime cache.
        assertTrue(GS:GetCurrentRecord() ~= nil, label .. " prime read")
        local fullAfterPrime = GS._opsValidationFullScans
        local itersAfterPrime = GS._opsValidationOrderIters
        local t0 = os.clock()
        for _ = 1, reps do
            assertTrue(GS:GetCurrentRecord() ~= nil, label .. " repeated read")
        end
        local elapsed = os.clock() - t0
        assertEq(GS._opsValidationFullScans, fullAfterPrime,
            label .. " repeated reads skip full scans scans="
                .. tostring(GS._opsValidationFullScans))
        assertEq(GS._opsValidationOrderIters, itersAfterPrime,
            label .. " repeated reads skip order iters iters="
                .. tostring(GS._opsValidationOrderIters))
        return elapsed, fullAfterPrime, itersAfterPrime
    end

    seedAccepted(1000)
    local elapsed1k = measureReads("B3-1k", 50)
    assertTrue(elapsed1k < 1.0, "B3: 50 reads at 1k ops stay bounded got=" .. tostring(elapsed1k))

    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    startCampaign()
    record = GS:GetCurrentRecord()
    datasetId = record.datasetId
    raw = SpectrumFederationDB.guildSupplies.guilds["club:42"]
    seedAccepted(4000)
    local elapsed4k = measureReads("B3-4k", 50)
    assertTrue(elapsed4k < 2.0, "B3: 50 reads at 4k ops stay bounded got=" .. tostring(elapsed4k))

    -- Controlled mutation invalidates; next read rescans once.
    local beforeMutFull = GS._opsValidationFullScans
    local mut = select(1, GS:NewConfigOperation("set-requested-item", { itemId = 8999 }, {
        itemId = 8999, goal = 1, removed = false,
    }))
    assertEq(GS:ApplyStagedConfigOperation(mut), "accepted", "B3: mutating write")
    assertTrue(GS:GetCurrentRecord() ~= nil, "B3: read after mutation")
    assertTrue(GS._opsValidationFullScans > beforeMutFull,
        "B3: mutation forces full revalidation")
    local afterMutFull = GS._opsValidationFullScans
    assertTrue(GS:GetCurrentRecord() ~= nil, "B3: second post-mutation read")
    assertEq(GS._opsValidationFullScans, afterMutFull,
        "B3: post-mutation cache hits again")

    -- Accepted bodies are snapshot copies: mutating the prepared op must not
    -- alter the retained accepted body (immutability invariant).
    local prepared = select(1, GS:NewConfigOperation("set-bank-tab", "bankTab", 4))
    assertTrue(prepared ~= nil, "B3: prepare bank tab")
    assertEq(GS:ApplyStagedConfigOperation(prepared), "accepted", "B3: admit bank tab")
    local stored = GS:GetCurrentRecord().operations.records[prepared.id]
    assertTrue(stored ~= nil and stored ~= prepared,
        "B3: accepted body is a distinct snapshot table")
    prepared.timestamp = math.huge
    assertTrue(stored.timestamp ~= math.huge,
        "B3: mutating prepared op does not corrupt accepted body")

    -- Malformed retained body via new ops-table identity (no private bump).
    raw = SpectrumFederationDB.guildSupplies.guilds["club:42"]
    local oldOps = raw.operations
    local badId = prepared.id
    oldOps.records[badId].timestamp = math.huge
    raw.operations = {
        records = oldOps.records,
        order = oldOps.order,
        heads = oldOps.heads,
        pending = oldOps.pending,
        conflicts = oldOps.conflicts,
        openConflicts = oldOps.openConflicts,
    }
    local exposed, reason = GS:GetCurrentRecord()
    assertNil(exposed, "B3: malformed retained body unavailable after replacement")
    assertEq(reason, "invalid_timestamp", "B3: malformed reason invalid_timestamp")
    -- Pending mutation path still invalidates via new ops-table identity.
    resetDb()
    initGS()
    setPlayer("Alice-Garona", "Player-1-Alice", 1)
    world.guild.clubId = 42
    settleRoster()
    GS:CreateStagedRecord()
    assertTrue(GS:GetCurrentRecord() ~= nil, "B3: pending-case prime")
    raw = SpectrumFederationDB.guildSupplies.guilds["club:42"]
    local fullBeforePending = GS._opsValidationFullScans
    raw.operations.pending["p-b3"] = {
        id = "p-b3",
        reason = "stale_base",
        body = { id = "other", kind = "set-bank-tab" },
        at = 1,
    }
    rebindOperations(raw)
    assertNil(select(1, GS:GetCurrentRecord()), "B3: bad pending unavailable")
    assertTrue(GS._opsValidationFullScans > fullBeforePending,
        "B3: pending mutation revalidates")
end

do
    -- C2/C3) Adjustment format locale + unlink disabled action string.
    resetDb()
    initGS()
    setPlayer("Bob-Garona", "Player-1-Bob", 5) -- unauthorized
    world.guild.clubId = 42
    settleRoster()
    -- Locale keys must ship accurate copy (not link-paste / linking).
    local L = (SF.Locale and SF.Locale.GetDictionary and SF.Locale:GetDictionary())
        or (_G.SpectrumFederationLocale)
    if type(L) ~= "table" then
        -- Fall back to raw enUS table loaded with the addon.
        L = ns and ns.L
    end
    -- Production Loc path uses SF.LocaleText / enUS keys.
    local adjKey = "GUILD_SUPPLIES_ERR_ADJUST_FORMAT"
    local unlinkKey = "GUILD_SUPPLIES_DISABLED_ACTION_UNLINK"
    local adjMsg = SF.LocaleText and SF.LocaleText(adjKey)
        or (SF.L and SF.L[adjKey])
    local unlinkMsg = SF.LocaleText and SF.LocaleText(unlinkKey)
        or (SF.L and SF.L[unlinkKey])
    -- Read directly from locale module table when helpers differ in harness.
    if (not adjMsg or adjMsg == adjKey) and type(_G) == "table" then
        -- Loaded via locales in test harness as part of addon.
        local en = nil
        if SF.GetLocaleTable then en = SF.GetLocaleTable() end
        if type(en) == "table" then
            adjMsg = en[adjKey] or adjMsg
            unlinkMsg = en[unlinkKey] or unlinkMsg
        end
    end
    -- Source-backed assertion: enUS.lua must define both keys accurately.
    local enUS = io.open("SpectrumFederation/locale/enUS.lua", "r")
    assertTrue(enUS ~= nil, "C2/C3: enUS.lua readable")
    local enBody = enUS:read("*a")
    enUS:close()
    assertTrue(enBody:find('GUILD_SUPPLIES_ERR_ADJUST_FORMAT', 1, true),
        "C2: adjust format locale key present")
    assertTrue(enBody:find("item ID, a signed quantity", 1, true),
        "C2: adjust format message states expected syntax")
    assertTrue(not (enBody:find('GUILD_SUPPLIES_ERR_ADJUST_FORMAT.-item link')),
        "C2: adjust format must not suggest item links")
    assertTrue(enBody:find('GUILD_SUPPLIES_DISABLED_ACTION_UNLINK', 1, true),
        "C3: unlink action locale key present")
    assertTrue(enBody:find('GUILD_SUPPLIES_DISABLED_ACTION_UNLINK"].-=.-"unlinking characters"', 1, true)
            or enBody:find('DISABLED_ACTION_UNLINK"] = "unlinking characters"', 1, true),
        "C3: unlink locale says unlinking characters")

    -- UI definition uses the unlink-specific key.
    local confSrc = io.open(
        "SpectrumFederation/modules/UI/Settings/Pages/GuildSuppliesConfiguration.lua", "r")
    assertTrue(confSrc ~= nil, "C2/C3: configuration page readable")
    local confBody = confSrc:read("*a")
    confSrc:close()
    assertTrue(confBody:find("GUILD_SUPPLIES_ERR_ADJUST_FORMAT", 1, true),
        "C2: adjustment onSubmit uses adjust-format locale")
    assertTrue(confBody:find("GUILD_SUPPLIES_DISABLED_ACTION_UNLINK", 1, true),
        "C3: unlink disabled tip uses unlink action key")
end

do
    -- Codex A) Bank-snapshot durable/export notifications coalesce (Retail ~25 rows).
    local itemId = 9201
    local record = seedActivatableCampaign(itemId, 100)
    GS:EnsureGossipProvider()
    armFreshBankSample(true)
    assertEq(select(2, GS:ActivateCanonicalDataset()), "accepted", "A-batch: activate")
    disarmFreshBankSample()
    record = GS:GetCurrentRecord()
    assertTrue(GS.IsLiveActive(record), "A-batch: live after activate")

    -- Near-cap directExports so each naive notify would rescan a large map.
    record.observations = record.observations or {}
    record.observations.directExports = record.observations.directExports or {}
    local nearCap = (GS.MAX_DIRECT_EVIDENCE_EXPORTS or 256) - 16
    for i = 1, nearCap do
        record.observations.directExports["gs:ev:seed-" .. i] = {
            schemaVersion = 1,
            witnessGuid = "Player-1-Alice",
            evidence = {
                coreSignature = "seed|" .. i,
                type = "deposit",
                donor = "Seed-Garona",
                itemId = itemId,
                quantity = 1,
                guildGuid = "42",
                bankTab = 2,
                generation = tonumber(record.accounting._consumables.generation) or 1,
                observedAt = world.time - 1000,
                ageHours = 0,
                approxTxnTime = world.time - 1000,
                occurrenceIndex = i,
                neighborsOlder = { "o" },
                neighborsNewer = { "n" },
                campaignId = record.currentCampaignId,
                datasetId = record.datasetId,
            },
        }
    end

    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesObservation.lua")
    loadModule("SpectrumFederation/modules/LootHelper/ConsumablesBankLog.lua")
    local BankLog = SF.ConsumablesBankLog
    local O = SF.ConsumablesObservation
    local ctx = BankLog:GuildSuppliesEligibleContext()
    assertTrue(ctx and ctx.source == "guildSupplies" and not ctx.sampleOnly,
        "A-batch: live GS observation context")

    local rows = {}
    world.bankTxnRows = { [2] = {} }
    for i = 1, 25 do
        local row = {
            "deposit",
            "Donor" .. i .. "-Garona",
            "|cffffffff|Hitem:" .. itemId .. "::::::::|h[Flask]|h|r",
            1, nil, nil, 0, 0, 0, 0,
        }
        world.bankTxnRows[2][i] = row
        rows[i] = {
            type = "deposit",
            name = "Donor" .. i .. "-Garona",
            itemLink = row[3],
            count = 1,
            year = 0, month = 0, day = 0, hour = 0,
            index = i,
        }
    end
    world.bankTxnCounts = { [2] = 25 }
    function GetNumGuildBankTransactions(tab) return world.bankTxnCounts[tab] or 0 end
    function GetGuildBankTransaction(tab, index)
        local r = world.bankTxnRows[tab] and world.bankTxnRows[tab][index]
        if not r then return nil end
        return unpack(r)
    end

    local ctxCalls = 0
    local priorGetCtx = GS.GetCurrentContext
    GS.GetCurrentContext = function(self)
        ctxCalls = ctxCalls + 1
        return priorGetCtx(self)
    end
    local rosterWalks = 0
    local priorRoster = GetGuildRosterInfo
    function GetGuildRosterInfo(i)
        rosterWalks = rosterWalks + 1
        if priorRoster then return priorRoster(i) end
        local m = world.guild.members[i]
        if m then return m.name, "R", 0, 80, "W", "Z", "", "", true, 0 end
    end

    world.notifyChanged = 0
    local notifyCalls = 0
    local priorNotify = GS.NotifyLocalDurableChange
    GS.NotifyLocalDurableChange = function(reason)
        notifyCalls = notifyCalls + 1
        return priorNotify(reason)
    end

    BankLog.bankOpen = true
    BankLog.active = true
    BankLog.activeContext = ctx
    BankLog.requireBankReopenForFreshness = false
    BankLog.awaitingLogUpdate = true
    BankLog.pendingQuery = {
        source = "guildSupplies",
        sampleOnly = false,
        profileId = ctx.profileId,
        guildGuid = ctx.guildGuid,
        bankTab = ctx.bankTab,
        generation = ctx.generation,
        campaignId = ctx.campaignId,
        datasetId = ctx.datasetId,
        requestedSet = ctx.requestedSet,
        observedBy = ctx.observedBy,
        eligibility = ctx.eligibility,
    }
    BankLog:ProcessLogUpdate("codex-a-batch")
    -- Drain any After(0) export-maint / UI notify timers.
    world.time = (world.time or 0) + 0.05
    flushTimers()
    if GS._exportMaintSyncDrain or GS._exportMaintIsIdle then
        drainExportMaint(64)
    end

    assertTrue((BankLog.lastStats and (BankLog.lastStats.admitted or 0)
            + (BankLog.lastStats.pending or 0)
            + (BankLog.lastStats.duplicate or 0)) >= 25
        or (BankLog.lastStats and (BankLog.lastStats.admitted or 0)
            + (BankLog.lastStats.pending or 0) >= 20),
        "A-batch: full log retains evidence admitted="
            .. tostring(BankLog.lastStats and BankLog.lastStats.admitted)
            .. " pending=" .. tostring(BankLog.lastStats and BankLog.lastStats.pending))
    -- Coalesce is measured by provider notifications / roster work, not by the
    -- number of deferred NotifyLocalDurableChange entries (those still run and
    -- return immediately while the batch is open).
    assertTrue(notifyCalls >= 25, "A-batch: per-row notifies still invoked API")
    assertTrue((world.notifyChanged or 0) >= 1
            and (world.notifyChanged or 0) <= 4,
        "A-batch: NotifyProviderChanged coalesced got=" .. tostring(world.notifyChanged))
    -- LiveWritesBlocked + CurrentGuildRecord must not scale with 25 rows.
    assertTrue(ctxCalls < 40,
        "A-batch: GetCurrentContext bounded got=" .. tostring(ctxCalls))
    assertTrue(rosterWalks < 200,
        "A-batch: roster walks bounded got=" .. tostring(rosterWalks))

    -- Evidence must remain exportable after the single flush.
    local exports = record.observations and record.observations.directExports or {}
    local newExports = 0
    for id, row in pairs(exports) do
        if type(id) == "string" and not id:find("gs:ev:seed-", 1, true)
            and type(row) == "table" then
            newExports = newExports + 1
        end
    end
    assertTrue(newExports >= 20,
        "A-batch: new directExports retained got=" .. tostring(newExports))

    GS.GetCurrentContext = priorGetCtx
    GS.NotifyLocalDurableChange = priorNotify
    GetGuildRosterInfo = priorRoster
    GetNumGuildBankTransactions = nil
    GetGuildBankTransaction = nil
end

do
    -- Codex B) Settings durable-change UI: selection revalidation + Logs refresh.
    local record = seedActivatableCampaign(9202, 20)
    GS:EnsureGossipProvider()
    -- Ensure no leaked bank-snapshot batch suppresses UI notifies.
    if GS.EndLocalDurableNotifyBatch then
        for _ = 1, 4 do GS.EndLocalDurableNotifyBatch() end
    end
    loadModule("SpectrumFederation/modules/UI/Settings/NavigationModel.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/Pages/GuildSuppliesLogs.lua")
    if not (SF.SettingsUI.pagesById and SF.SettingsUI.pagesById.guildSuppliesConfiguration) then
        loadModule("SpectrumFederation/modules/UI/Settings/Pages/GuildSuppliesConfiguration.lua")
    end
    local Nav = SF.SettingsNavigationModel
    local ui = SF.SettingsUI
    assertTrue(Nav and ui and ui.pagesById, "B-ui: settings registry present")

    assertEq(ui.pagesById.lootHelperConsumables, nil,
        "B-ui: legacy Consumables page is not registered while staged")
    assertEq(ui.pagesById.lootHelperConsumableLogs, nil,
        "B-ui: legacy Consumable Logs page is not registered while staged")
    assertTrue(ui.pagesById.guildSuppliesConfiguration ~= nil,
        "B-ui: Raid Supplies Configuration remains registered while staged")
    assertTrue(ui.pagesById.guildSuppliesLogs ~= nil,
        "B-ui: Raid Supplies Logs remains registered while staged")
    assertEq(Nav.IsContentPage(ui, "guildSuppliesConfiguration"), true,
        "B-ui: Configuration is a content page while staged")
    assertEq(Nav.IsContentPage(ui, "guildSuppliesLogs"), true,
        "B-ui: Logs is a content page while staged")

    local uiReasons = {}
    assertTrue(type(GS.RegisterUIListener) == "function", "B-ui: RegisterUIListener present")
    assertTrue(type(GS.NotifyUI) == "function", "B-ui: NotifyUI present")
    GS.RegisterUIListener(function(reason)
        uiReasons[#uiReasons + 1] = reason
    end)
    -- Sanity: direct poke reaches the listener through the coalesced timer path.
    GS.NotifyUI("probe")
    world.time = (world.time or 0) + 0.05
    flushTimers()
    assertTrue(#uiReasons >= 1 and uiReasons[1] == "probe",
        "B-ui: direct NotifyUI delivers to listeners")

    armFreshBankSample(true)
    assertEq(select(2, GS:ActivateCanonicalDataset()), "accepted", "B-ui: activate")
    disarmFreshBankSample()
    world.time = (world.time or 0) + 0.05
    flushTimers()

    assertTrue(#uiReasons >= 2, "B-ui: activation notifies Settings listeners")
    local sawActivation = false
    for i = 1, #uiReasons do
        if uiReasons[i] == "activation" then sawActivation = true end
        assertTrue(uiReasons[i] ~= "export-maint",
            "B-ui: export-maint must not reach UI listeners")
    end
    assertTrue(sawActivation, "B-ui: activation reason delivered")
    assertEq(ui.pagesById.lootHelperConsumables, nil,
        "B-ui: legacy Consumables page stays unregistered after activation")
    assertEq(ui.pagesById.lootHelperConsumableLogs, nil,
        "B-ui: legacy Consumable Logs page stays unregistered after activation")
    assertEq(Nav.IsContentPage(ui, "lootHelperConsumables"), false,
        "B-ui: unknown legacy id is not a content page")
    assertEq(Nav.IsContentPage(ui, "guildSuppliesConfiguration"), true,
        "B-ui: Configuration remains a content page after activation")
    assertEq(Nav.IsContentPage(ui, "guildSuppliesLogs"), true,
        "B-ui: Logs remains a content page after activation")

    -- Earlier suite stubs may RegisterPage without UpsertCategoryFromPage.
    -- Mirror production Loot Helper category + always-available General fallback
    -- so ResolveSidebarSelect leaves an unknown legacy tab id.
    local categoryId = "lootHelper"
    ui.categoriesById = ui.categoriesById or {}
    ui.categories = ui.categories or {}
    ui.pages = ui.pages or {}
    if not ui.categoriesById[categoryId] then
        local cat = {
            id = categoryId,
            name = "Loot Helper",
            navLabel = "Loot Helper",
            defaultChildId = "lootHelperGeneral",
            enabled = true,
            enablementResolved = true,
            order = 20,
            source = "page",
        }
        ui.categoriesById[categoryId] = cat
        ui.categories[#ui.categories + 1] = cat
    end
    if not ui.pagesById.lootHelperGeneral then
        local general = {
            id = "lootHelperGeneral",
            parentId = categoryId,
            categoryId = categoryId,
            name = "General Settings",
            navLabel = "General",
            order = 20.5,
        }
        ui.pagesById.lootHelperGeneral = general
        ui.pages[#ui.pages + 1] = general
    end

    -- ResolveSidebarSelect must not restore the retired last-tab.
    local session = {
        currentCategoryId = categoryId,
        currentPageId = "lootHelperConsumables",
        lastPageByCategory = { [categoryId] = "lootHelperConsumables" },
    }
    local sidebar = Nav.ResolveSidebarSelect(ui, session, categoryId)
    assertTrue(sidebar.pageId ~= "lootHelperConsumables",
        "B-ui: sidebar fallback leaves retired consumables page got="
            .. tostring(sidebar.pageId))
    assertEq(sidebar.pageId, "lootHelperGeneral",
        "B-ui: sidebar falls back to default Loot Helper page")

    -- StandaloneWindow:Show revalidates selection without sidebar rebuild.
    local winSrc = io.open("SpectrumFederation/modules/UI/Settings/StandaloneWindow.lua", "r")
    assertTrue(winSrc ~= nil, "B-ui: StandaloneWindow readable")
    local winBody = winSrc:read("*a")
    winSrc:close()
    assertTrue(winBody:find("RevalidateSelection", 1, true)
            and winBody:find("function SettingsWindow:Show", 1, true),
        "B-ui: Show path references RevalidateSelection")
    assertTrue(winBody:find("HandleDurableAvailabilityChange", 1, true),
        "B-ui: SettingsWindow gates durable notifies via HandleDurableAvailabilityChange")
    assertTrue(winBody:find("RegisterUIListener", 1, true),
        "B-ui: SettingsWindow registers GS durable UI listener")

    -- Visible Guild Supplies Logs refreshes on durable notify; hidden does not.
    local Logs = SF.SettingsUI.pagesById.guildSuppliesLogs
        or (SF.SettingsPages and SF.SettingsPages.GuildSuppliesLogs)
    -- Page module stores itself on SF via RegisterPage; locate Refreshable panel.
    local pageMod = nil
    for _, p in pairs(ui.pagesById or {}) do
        if p.id == "guildSuppliesLogs" or (p.name and tostring(p.name):find("Logs")) then
            if p.id and tostring(p.id):find("guildSupplies", 1, true)
                and tostring(p.id):find("Logs", 1, true) then
                pageMod = p
                break
            end
        end
    end
    -- Prefer the module table attached during load.
    pageMod = pageMod or SF.GuildSuppliesLogsPage
    -- Build a minimal visible panel and install QueueRefresh path via page API.
    local refreshCount = 0
    local panel = {
        shown = true,
        visible = true,
        IsShown = function(self) return self.shown end,
        IsVisible = function(self) return self.visible end,
        HookScript = function() end,
    }
    -- Locate the Logs page object that owns Build/Refresh (registered page may wrap it).
    local logsPageObj = nil
    for _, mod in pairs({ SF.SettingsPages, SF }) do
        if type(mod) == "table" then
            for k, v in pairs(mod) do
                if type(v) == "table" and type(v.Refresh) == "function"
                    and type(v.Build) == "function"
                    and (k == "GuildSuppliesLogs" or (v.id == "guildSuppliesLogs")) then
                    logsPageObj = v
                end
            end
        end
    end
    -- Fall back: the loaded page file registers into SettingsUI; use definition id.
    if not logsPageObj then
        for _, p in pairs(ui.pagesById or {}) do
            if p.id == "guildSuppliesLogs" then
                logsPageObj = p
                break
            end
        end
    end
    assertTrue(logsPageObj and type(logsPageObj.Refresh) == "function",
        "B-ui: Guild Supplies Logs page object available")
    local priorRefresh = logsPageObj.Refresh
    logsPageObj.Refresh = function(self, p)
        refreshCount = refreshCount + 1
        if priorRefresh then
            return priorRefresh(self, p)
        end
    end
    if logsPageObj.Build then
        pcall(function() logsPageObj:Build(panel) end)
    end
    logsPageObj.panel = panel
    panel.shown = true
    panel.visible = true
    local beforeRefresh = refreshCount
    GS.NotifyLocalDurableChange("ledger")
    world.time = (world.time or 0) + 0.05
    flushTimers()
    assertTrue(refreshCount > beforeRefresh,
        "B-ui: visible Logs refreshes on durable ledger notify")

    -- Hidden / closed Settings: no additional refresh.
    panel.visible = false
    panel.shown = false
    local midRefresh = refreshCount
    GS.NotifyLocalDurableChange("ledger")
    world.time = (world.time or 0) + 0.05
    flushTimers()
    assertEq(refreshCount, midRefresh,
        "B-ui: hidden Logs does not refresh on durable notify")

    -- export-maint must not poke UI.
    local uiBeforeMaint = #uiReasons
    GS.NotifyLocalDurableChange("export-maint")
    world.time = (world.time or 0) + 0.05
    flushTimers()
    assertEq(#uiReasons, uiBeforeMaint,
        "B-ui: export-maint does not enqueue UI notify")

    -- Repeated show/hide cycles stay idle (no listener accumulation storm).
    panel.visible = true
    panel.shown = true
    for _ = 1, 5 do
        GS.NotifyLocalDurableChange("evidence")
    end
    world.time = (world.time or 0) + 0.05
    flushTimers()
    assertTrue(refreshCount < midRefresh + 10,
        "B-ui: coalesced durable notifies stay bounded refreshes="
            .. tostring(refreshCount - midRefresh))

    logsPageObj.Refresh = priorRefresh
    assertEq(#world.chat, 0, "B-ui: no Chat from durable UI notify")
end

do
    -- Codex B-lifecycle) Production SettingsWindow selection revalidation without
    -- nav frame churn. Measures CreateFrame + nav object identity; does not stub
    -- HandleRegistryChanged / RevalidateSelection.
    local priorCreateFrame = CreateFrame
    local createFrameCount = 0
    local navCreateCount = 0
    local navParentRef = { panel = nil }
    local function makeRegion(kind, name, parent)
        local region = {
            kind = kind,
            name = name,
            parent = parent,
            shown = true,
            height = 0,
            width = 0,
            points = {},
            scripts = {},
            children = {},
        }
        function region:SetPoint() end
        function region:ClearAllPoints() end
        function region:SetHeight(h) self.height = h end
        function region:GetHeight() return self.height end
        function region:SetWidth(w) self.width = w end
        function region:SetSize(w, h) self.width = w self.height = h end
        function region:Show() self.shown = true end
        function region:Hide() self.shown = false end
        function region:IsShown() return self.shown and true or false end
        function region:SetAllPoints() end
        function region:SetColorTexture() end
        function region:SetTexture() end
        function region:SetTexCoord() end
        function region:SetText(t) self.text = t end
        function region:SetTextColor() end
        function region:SetJustifyH() end
        function region:SetJustifyV() end
        function region:SetWordWrap() end
        function region:SetFontObject() end
        function region:SetScript(e, fn) self.scripts[e] = fn end
        function region:HookScript(e, fn) self.scripts["hook:" .. e] = fn end
        function region:EnableMouse() end
        function region:SetParent(p) self.parent = p end
        function region:CreateTexture()
            local t = makeRegion("Texture", nil, self)
            self.children[#self.children + 1] = t
            return t
        end
        function region:CreateFontString()
            local f = makeRegion("FontString", nil, self)
            self.children[#self.children + 1] = f
            return f
        end
        return region
    end
    function CreateFrame(frameType, name, parent)
        createFrameCount = createFrameCount + 1
        if navParentRef.panel and parent == navParentRef.panel then
            navCreateCount = navCreateCount + 1
        end
        return makeRegion(frameType or "Frame", name, parent)
    end

    loadModule("SpectrumFederation/modules/UI/Settings/NavigationModel.lua")
    loadModule("SpectrumFederation/modules/UI/Settings/StandaloneWindow.lua")
    local SettingsWindow = SF.SettingsWindow
    local Nav = SF.SettingsNavigationModel
    local ui = SF.SettingsUI
    assertTrue(SettingsWindow and SettingsWindow.RevalidateSelection
            and SettingsWindow.HandleDurableAvailabilityChange
            and SettingsWindow.HandleRegistryChanged,
        "B-life: SettingsWindow lifecycle APIs present")

    -- Ensure production-shaped Loot Helper category + fallback pages.
    ui.categoriesById = ui.categoriesById or {}
    ui.categories = ui.categories or {}
    ui.pagesById = ui.pagesById or {}
    ui.pages = ui.pages or {}
    -- StandaloneWindow GetCategory requires the Registry API (not a raw map).
    function ui:GetCategory(categoryId)
        if not categoryId then
            return nil
        end
        return self.categoriesById and self.categoriesById[categoryId] or nil
    end
    local function ensurePage(page)
        if ui.pagesById[page.id] then
            local existing = ui.pagesById[page.id]
            for k, v in pairs(page) do
                if existing[k] == nil then existing[k] = v end
            end
            return existing
        end
        ui.pagesById[page.id] = page
        ui.pages[#ui.pages + 1] = page
        return page
    end
    if not ui.categoriesById.lootHelper then
        local cat = {
            id = "lootHelper",
            name = "Loot Helper",
            navLabel = "Loot Helper",
            defaultChildId = "lootHelperGeneral",
            enabled = true,
            enablementResolved = true,
            order = 20,
            group = "Raid Tools",
        }
        ui.categoriesById.lootHelper = cat
        -- Categories must be an array for BuildSidebarItems ipairs traversal.
        local found = false
        for _, c in ipairs(ui.categories) do
            if c.id == "lootHelper" then found = true break end
        end
        if not found then
            ui.categories[#ui.categories + 1] = cat
        end
    end
    ensurePage({
        id = "lootHelperGeneral",
        parentId = "lootHelper",
        categoryId = "lootHelper",
        name = "General Settings",
        navLabel = "General",
        order = 20.5,
        Build = function() end,
        Refresh = function() end,
    })
    local consumablesPage = ensurePage({
        id = "lootHelperConsumables",
        parentId = "lootHelper",
        categoryId = "lootHelper",
        name = "Raid Consumables",
        navLabel = "Consumables",
        order = 23.6,
        available = function()
            local C = SF.Consumables
            if C and C.LegacyWritersAllowed then
                return C.LegacyWritersAllowed()
            end
            return true
        end,
        Build = function() end,
        Refresh = function() end,
    })
    assertTrue(type(consumablesPage.available) == "function", "B-life: consumables available hook")
    -- Prior B-ui block activates Guild Supplies for this guild; Consumables is retired.
    assertEq(Nav.IsPageAvailable(consumablesPage), false,
        "B-life: consumables already retired after prior activation")
    GS:EnsureGossipProvider()
    if GS.EndLocalDurableNotifyBatch then
        for _ = 1, 4 do GS.EndLocalDurableNotifyBatch() end
    end

    -- Minimal window shell so production RebuildNavRows / Show paths run.
    SettingsWindow.initialized = true
    SettingsWindow.navPanel = CreateFrame("Frame", "SF_TestNav")
    navParentRef.panel = SettingsWindow.navPanel
    SettingsWindow.contentHost = CreateFrame("Frame", "SF_TestHost")
    SettingsWindow.contentTitleText = { SetText = function() end }
    SettingsWindow.contentDescriptionText = {
        SetText = function() end,
        ClearAllPoints = function() end,
        SetPoint = function() end,
    }
    SettingsWindow.contentHeadingText = {
        SetText = function() end,
        Show = function() end,
        Hide = function() end,
    }
    SettingsWindow.contentHeader = { SetHeight = function() end }
    SettingsWindow.tabBar = nil
    SettingsWindow.emptyState = nil
    SettingsWindow.impersonationBanner = nil
    SettingsWindow.pagePanels = {}
    SettingsWindow.navButtons = {}
    SettingsWindow.navGroups = {}
    SettingsWindow.navItems = {}
    SettingsWindow.lastPageByCategory = {}
    SettingsWindow._contentPagesSig = nil
    SettingsWindow._selectionRevalidatePending = false
    SettingsWindow._gsDurableListener = true -- Init already registered in prior loads; avoid double
    -- Register durable listener explicitly for this window instance path.
    local durableCalls = 0
    GS.RegisterUIListener(function()
        durableCalls = durableCalls + 1
        SettingsWindow:HandleDurableAvailabilityChange()
    end)

    SettingsWindow.currentCategoryId = "lootHelper"
    SettingsWindow.currentPageId = "lootHelperConsumables"
    SettingsWindow.lastPageByCategory.lootHelper = "lootHelperConsumables"
    local shown = true
    SettingsWindow.frame = {
        Show = function() shown = true end,
        Hide = function() shown = false end,
        IsShown = function() return shown end,
    }
    SettingsWindow.RefreshEnablementIfNeeded = function() end
    SettingsWindow.UpdateImpersonationBanner = function() end
    SettingsWindow.ApplyPreferredWindowMin = function() end
    -- Avoid PageBuilder/ScrollFrame dependencies; this suite measures nav churn.
    SettingsWindow.GetOrCreatePagePanel = function(self, pageId)
        if self.pagePanels[pageId] then
            return self.pagePanels[pageId]
        end
        local panel = CreateFrame("Frame", nil, self.contentHost)
        panel:Hide()
        self.pagePanels[pageId] = panel
        return panel
    end
    for _, id in ipairs({ "lootHelperGeneral", "lootHelperConsumables" }) do
        local p = ui.pagesById[id]
        if p then
            p.Build = function() end
            p.Refresh = function() end
        end
    end

    navCreateCount = 0
    createFrameCount = 0
    SettingsWindow:RebuildNavRows()
    local navAfterBuild = navCreateCount
    assertTrue(navAfterBuild > 0, "B-life: initial RebuildNavRows creates nav frames got="
        .. tostring(navAfterBuild))
    local buttonSnapshot = {}
    local buttonCount = 0
    for id, btn in pairs(SettingsWindow.navButtons) do
        buttonSnapshot[id] = btn
        buttonCount = buttonCount + 1
    end
    assertTrue(buttonCount >= 1, "B-life: sidebar has category buttons")
    -- Capture content-page signature so later evidence notifies are true no-ops.
    SettingsWindow:RevalidateSelection()
    assertEq(navCreateCount, navAfterBuild,
        "B-life: RevalidateSelection after build creates no nav frames")

    -- Activation-shaped durable UI notify while Settings is open on Consumables.
    -- Use NotifyUI (production delivery after NotifyLocalDurableChange) so export
    -- rebuild side effects cannot mask the Settings listener path.
    shown = true
    SettingsWindow.currentPageId = "lootHelperConsumables"
    SettingsWindow.lastPageByCategory.lootHelper = "lootHelperConsumables"
    assertEq(Nav.IsContentPage(ui, "lootHelperConsumables"), false,
        "B-life: retired page is not a content page before open notify")
    local navBeforeOpenNotify = navCreateCount
    local durableBefore = durableCalls
    GS.NotifyUI("activation")
    assertTrue(durableCalls > durableBefore,
        "B-life: NotifyUI reaches Settings durable listener")
    assertTrue(SettingsWindow.currentPageId ~= "lootHelperConsumables",
        "B-life: open activation notify leaves retired page got="
            .. tostring(SettingsWindow.currentPageId))
    assertEq(SettingsWindow.currentPageId, "lootHelperGeneral",
        "B-life: open activation notify selects General fallback")
    assertEq(navCreateCount, navBeforeOpenNotify,
        "B-life: open activation notify creates no nav frames")
    for id, btn in pairs(buttonSnapshot) do
        assertTrue(SettingsWindow.navButtons[id] == btn,
            "B-life: nav button identity stable after activation notify id=" .. tostring(id))
    end

    -- Ordinary evidence/ledger notifies must not rebuild navigation.
    local midNav = navCreateCount
    local midPage = SettingsWindow.currentPageId
    local midTotal = createFrameCount
    for _ = 1, 12 do
        GS.NotifyUI("evidence")
        GS.NotifyUI("ledger")
        GS.NotifyUI("remote-evidence")
    end
    assertEq(navCreateCount, midNav,
        "B-life: evidence/ledger notifies create no nav frames")
    assertEq(createFrameCount, midTotal,
        "B-life: evidence/ledger notifies create no frames at all")
    assertEq(SettingsWindow.currentPageId, midPage,
        "B-life: evidence/ledger preserve selection")

    -- Activation while Settings is closed, then reopen.
    SettingsWindow.currentPageId = "lootHelperConsumables"
    SettingsWindow.lastPageByCategory.lootHelper = "lootHelperConsumables"
    shown = false
    local closedNav = navCreateCount
    local closedTotal = createFrameCount
    GS.NotifyUI("activation")
    assertEq(navCreateCount, closedNav,
        "B-life: hidden durable notify creates no nav frames")
    assertEq(createFrameCount, closedTotal,
        "B-life: hidden durable notify creates no frames")
    assertEq(SettingsWindow.currentPageId, "lootHelperConsumables",
        "B-life: hidden durable notify defers selection change")
    assertEq(SettingsWindow._selectionRevalidatePending, true,
        "B-life: hidden durable notify marks pending revalidate")
    SettingsWindow:Show()
    assertTrue(SettingsWindow.currentPageId ~= "lootHelperConsumables",
        "B-life: Show after closed activation leaves retired page got="
            .. tostring(SettingsWindow.currentPageId))
    assertEq(SettingsWindow.currentPageId, "lootHelperGeneral",
        "B-life: Show selects General after deferred activation")
    assertEq(navCreateCount, closedNav,
        "B-life: Show revalidate creates no nav frames")

    -- Direct ShowPage of retired tab must not restore it.
    SettingsWindow:ShowPage("lootHelperConsumables")
    assertTrue(SettingsWindow.currentPageId ~= "lootHelperConsumables",
        "B-life: ShowPage(retired) does not restore got="
            .. tostring(SettingsWindow.currentPageId))
    local showPageResolved = Nav.ResolveShowPage(ui, SettingsWindow:Session(), "lootHelperConsumables")
    assertTrue(showPageResolved.pageId ~= "lootHelperConsumables",
        "B-life: ResolveShowPage(retired) falls back got="
            .. tostring(showPageResolved.pageId))

    -- 80 Show/Hide cycles: no nav frame accumulation.
    local cycleNav = navCreateCount
    local cycleButtons = {}
    for id, btn in pairs(SettingsWindow.navButtons) do
        cycleButtons[id] = btn
    end
    for _ = 1, 80 do
        SettingsWindow:Hide()
        SettingsWindow:Show()
    end
    assertEq(navCreateCount, cycleNav,
        "B-life: 80 Show/Hide cycles create no nav frames delta="
            .. tostring(navCreateCount - cycleNav))
    for id, btn in pairs(cycleButtons) do
        assertTrue(SettingsWindow.navButtons[id] == btn,
            "B-life: nav button identity stable across Show/Hide id=" .. tostring(id))
    end

    -- Genuine registry change still rebuilds navigation.
    local beforeRegistryNav = navCreateCount
    local oldLootBtn = SettingsWindow.navButtons.lootHelper
    SettingsWindow:HandleRegistryChanged()
    assertTrue(navCreateCount > beforeRegistryNav,
        "B-life: HandleRegistryChanged recreates nav frames")
    assertTrue(SettingsWindow.navButtons.lootHelper ~= nil, "B-life: rebuilt lootHelper button")
    assertTrue(SettingsWindow.navButtons.lootHelper ~= oldLootBtn,
        "B-life: registry rebuild replaces prior nav button objects")

    CreateFrame = priorCreateFrame
    assertEq(#world.chat, 0, "B-life: no Chat from lifecycle repair")
end

