    assertTrue(#O.ListEligibleEvidenceFromSnapshot(snapshot) >= n,
        "val: C snapshot yields eligible deposits")

    world.notifyChanged = 0
    local uiCount = 0
    GS.RegisterUIListener(function()
        uiCount = uiCount + 1
    end)
    valuationTsmCalls = 0
    tsmByKey = {}
