    valuationTsmCalls = 0
    tsmByKey = {}
    local phase = 0
    valuationTsmValue = function(item)
        phase = phase + 1
        if phase == 1 then
            return nil
        end
        return 777
    end
    local rows2 = {
        {
            type = "deposit",
            name = "C2LaterA-Garona",
            itemLink = "|cffffffff|Hitem:" .. itemId .. "::::::::|h[Item]|h|r",
            itemID = itemId,
            count = 2,
